INSERT INTO `biz_question` VALUES (79, 'typing', '1956 年美国达特茅斯会议正式提出 “人工智能（AI）” 概念，该年被视为人工智能元年。英国数学家阿兰・图灵在《计算机器与智能》中提出 “图灵测试”，以提问者判断失误率≥30% 作为机器具备人类智能的标准。人工智能发展并非一帆风顺，经历了三起两落的历程，不同阶段核心研究方向从符号推理逐步拓展。', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 4, 143, 104, '19157727791', '2026-01-19 15:14:14', '19157727791', '2026-01-19 15:14:22');
INSERT INTO `biz_question` VALUES (80, 'choice', '被普遍认为 “人工智能元年” 的是哪一年', 8, '1', 1, '1956', '1943', '1978', '1999', 'A', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-19 15:15:25', '', NULL);
INSERT INTO `biz_question` VALUES (81, 'practical', '操作题', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/01/19/课后作业_20260119151609A133.docx', '/profile/upload/2026/01/19/课后作业_20260119151609A133.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-01-19 15:16:24', '', NULL);
INSERT INTO `biz_question` VALUES (104, 'choice', '在HTML网页代码中，用于定义网页“主体内容”的标签是？', 8, '0', 1, '<head>', '<body>', '<title>', '<html>', 'B', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (105, 'choice', '想要在网页中插入一张图片，应该使用以下哪个标签？', 8, '0', 1, '<img>', '<pic>', '<image>', '<src>', 'A', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (106, 'choice', '下列关于HTML标签的说法，错误的是？', 8, '0', 1, 'HTML标签通常是成对出现的', '<br>标签用于换行，它没有结束标签', 'HTML是不区分大小写的', '<html>标签表示网页的结束', 'D', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (107, 'choice', '网页文件的扩展名通常是？', 8, '0', 1, '.txt', '.doc', '.html', '.ppt', 'C', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:56', '', NULL);
INSERT INTO `biz_question` VALUES (108, 'choice', '如果要在网页标题栏显示“期末考试”，代码应写在哪个标签之间？', 8, '0', 1, '<body>...</body>', '<p>...</p>', '<title>...</title>', '<h1>...</h1>', 'C', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:57', '', NULL);
INSERT INTO `biz_question` VALUES (109, 'judgment', '我们可以使用“记事本”软件编写HTML代码，保存时将后缀名改为.html即可用浏览器打开。', 8, '0', 1, '', '', '', '', 'T', '', NULL, NULL, NULL, 'N', NULL, NULL, 104, '19157727791', '2026-01-20 12:56:57', '', NULL);
INSERT INTO `biz_question` VALUES (110, 'typing', '互联网应用极大改变了我们的生活方式，从在线学习到电子支付，数据早已无处不在。网页是互联网数据呈现的重要载体，而超文本标记语言HTML则是制作网页的基石。在HTML代码中，标签通常成对出现，例如BODY标签定义了网页的主体内容，IMG标签用于插入图像。我们在享受便捷的同时，绝不能忽视网络安全隐患。为了保护个人隐私和数据资产，我们需要养成定期备份数据的习惯。', 8, '0', 1, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 178, 104, '19157727791', '2026-01-20 12:56:57', '', NULL);
INSERT INTO `biz_question` VALUES (111, 'typing', '核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。', 6, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 110, 104, '19157727791', '2026-01-20 13:01:00', '', NULL);
INSERT INTO `biz_question` VALUES (112, 'practical', '操作题', 8, '0', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/01/20/课后作业_20260120130453A040.docx', '/profile/upload/2026/01/20/课后作业_20260120130453A040.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-01-20 13:05:03', '', NULL);
INSERT INTO `biz_question` VALUES (113, 'choice', '下列哪一项属于算法的基本特征？', 6, '0', 1, '随意性', '有限性', '娱乐性', '模糊性', 'B', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:35:37', '', NULL);
INSERT INTO `biz_question` VALUES (114, 'choice', '在“鸡兔同笼”问题中，常用的算法思想是', 6, '0', 1, '排序法 ', '枚举法', '加密法', '压缩', 'B', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:36:29', '', NULL);
INSERT INTO `biz_question` VALUES (115, 'choice', '猜数字游戏中，用于反复让用户输入的结构是', 6, '0', 1, '顺序结构', '分支结构', '循环结构', '选择结构', 'C', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:37:19', '', NULL);
INSERT INTO `biz_question` VALUES (116, 'judgment', '算法对生活只有好处，没有任何问题', 6, '0', NULL, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:37:47', '', NULL);
INSERT INTO `biz_question` VALUES (117, 'judgment', '二分查找比顺序查找效率低', 6, '0', NULL, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:38:09', '', NULL);
INSERT INTO `biz_question` VALUES (118, 'practical', '六年级', 6, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/01/21/考试操作题_20260121124339A213.docx', '/profile/upload/2026/01/21/考试操作题_20260121124339A213.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-01-21 12:43:53', '', NULL);
INSERT INTO `biz_question` VALUES (121, 'typing', '人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。', 8, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 191, 104, '19157727791', '2026-03-03 09:22:20', '', NULL);
INSERT INTO `biz_question` VALUES (122, 'typing', '数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 219, 104, '19157727791', '2026-03-03 10:16:49', '', NULL);
INSERT INTO `biz_question` VALUES (123, 'practical', '人工智能技术基础课后练习', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.docx', '/profile/upload/2026/03/03/八下第3课作业_20260303101723A002.pdf', 'failed', 'Y', NULL, NULL, 104, '19157727791', '2026-03-03 10:17:39', '', NULL);
INSERT INTO `biz_question` VALUES (124, 'typing', '在自动控制系统中，将输出量通过检测装置反馈到输入端并与输入量进行比较的过程，就是反馈 。通过输出量和输入量的比较，实现控制系统的输出在预设范围内，反馈在其中发挥了重要的作用 。反馈在保证系统正常运行中也发挥了重要的作用 。', 6, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 108, 104, '19157727791', '2026-03-03 11:07:50', '', NULL);
INSERT INTO `biz_question` VALUES (127, 'practical', '人工智能应用课后练习', 8, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.docx', '/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-04 09:18:36', '', NULL);
INSERT INTO `biz_question` VALUES (128, 'typing', '物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。', 7, '0', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 183, 896, '675077', '2026-03-05 09:28:14', '', NULL);
INSERT INTO `biz_question` VALUES (129, 'typing', '图像识别技术是人工智能的一个重要领域。它是指对图像进行对象识别，以识别各种不同模式的目标和对像的技术。 图像识别技术可能是以图像的主要特征为基础的。每个图像都有它的特征，如字母A有个尖，P有个圈、而Y的中心有个锐角等。由此可见，在图像识别过程中，知觉机制必须排除输入的多余信息,抽出关键的信息。同时,在大脑里必定有一个负责整合信息的机制，它能把分阶段获得的信息整理成一个完整的知觉映象。', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 192, 896, '675077', '2026-03-09 09:06:03', '', NULL);
INSERT INTO `biz_question` VALUES (130, 'practical', '上传图像识别导学单', 8, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/09/导学单 - 图像识别技术_20260309093017A180.docx', '/profile/upload/2026/03/09/导学单 - 图像识别技术_20260309093017A180.pdf', 'failed', 'Y', NULL, NULL, 896, '675077', '2026-03-09 09:30:38', '', NULL);
INSERT INTO `biz_question` VALUES (131, 'practical', '人工智能基础课后练习', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.docx', '/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-09 10:41:02', '', NULL);
INSERT INTO `biz_question` VALUES (132, 'practical', '上传生成二维码', 7, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/09/灯塔操作手册_20260309112613A182.docx', '/profile/upload/2026/03/09/灯塔操作手册_20260309112613A182.pdf', 'success', 'Y', NULL, NULL, 896, '675077', '2026-03-09 11:26:23', '', NULL);
INSERT INTO `biz_question` VALUES (161, 'choice', '水分传感器是物联网架构中（     ）的设备？', 7, '1', 2, '应用层', '平台层', '网络层', '感知层', 'D', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '', NULL);
INSERT INTO `biz_question` VALUES (162, 'choice', '利用云计算、数据挖掘以及模糊识别等智能技术，对接收到的海量数据与信息进行分析、处理，以进行智能化决策，体现了物联网的（         ）特征。', 7, '1', 2, '全面感知', '可靠传递', '可靠决策', '智能处理', 'D', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '', NULL);
INSERT INTO `biz_question` VALUES (163, 'choice', '物联网的（       ）功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。', 7, '1', 2, '应用层', '平台层', '网络层', '感知层', 'B', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:18');
INSERT INTO `biz_question` VALUES (164, 'choice', '自动浇灌物联系统原型中，物联数据中台是属于（       ）', 7, '1', 2, '应用层', '平台层', '网络层', '感知层', 'B', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:14');
INSERT INTO `biz_question` VALUES (165, 'choice', '关于只允许本小区车辆进入的无人看守停车场，下列说法不正确的是（     ）', 7, '1', 2, '利用摄像头拍录汽车牌照图片属于物联网感知层；', '将图片传送到平台层进行数据处理需要通过网络层。', '平台层中运用人工智能图像识别技术识别图片中的车牌号码判断是否为本小区车辆，体现了物联网的全面感知特征。', '拦车杆根据指令升起，是物联网应用层上的智能应用。', 'C', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:21');
INSERT INTO `biz_question` VALUES (166, 'judgment', '物联网体系架构中，平台层相当于人的皮肤', 7, '1', 2, '', '', '', '', 'F', '', NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-09 16:37:05', '960250', '2026-03-09 16:37:36');
INSERT INTO `biz_question` VALUES (167, 'typing', '物联网是互联网充分发展的产物，是物理世界和数字世界之间的桥梁。物联网具有全面感知、可靠传递、智能处理等特征。物联网一般由感知层、网络层、平台层、应用层四层组成。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。平台层是在云平台基础上构建的基础计算设施，功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。应用层是物联网和用户的接口。', 7, '1', 2, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 222, 1587, '960250', '2026-03-09 16:37:05', '', NULL);
INSERT INTO `biz_question` VALUES (168, 'typing', '人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。', 8, '1', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 179, 104, '19157727791', '2026-03-10 10:46:17', '', NULL);
INSERT INTO `biz_question` VALUES (169, 'practical', '课堂探究', 8, '1', 4, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.docx', '/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-10 15:15:15', '', NULL);
INSERT INTO `biz_question` VALUES (170, 'typing', '反馈的实现是通过传感器对系统的输出量进行检测，并与输入量比较来判断是否达成预期的过程。传感器如同人体感官，负责获取环境信息。比较器接收传感器传回的实际输出量，与预设输入量对比计算出偏差值。', 6, '1', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 5, 94, 104, '19157727791', '2026-03-10 19:45:04', '', NULL);
INSERT INTO `biz_question` VALUES (171, 'practical', '观看智能浇灌系统和智能通风系统展示视频，选择其一填表：\n', 7, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/11/课堂任务_20260311145344A484.docx', '/profile/upload/2026/03/11/课堂任务_20260311145344A484.pdf', 'success', 'Y', NULL, NULL, 1587, '960250', '2026-03-11 14:54:28', '', NULL);
INSERT INTO `biz_question` VALUES (172, 'typing', '数字资源的用途非常广泛：数字图书馆中的期刊资源为研究提供帮助，字库提供了各种字体让电子作文富有个性……各类资源库有不同的用途。丰富的文本、精美的图片、动听的音乐、精彩的视频等数字资源的使用，让学习和生活变得丰富多彩。', 3, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 108, 1912, '15356061316', '2026-03-12 09:31:48', '', NULL);
INSERT INTO `biz_question` VALUES (173, 'typing', '数字图像由许许多多的像素组成。图像尺寸一般用像素表示，通常像素越多，图像尺寸越大，清晰度也越高。在数字图像文件中，每个像素都由二进制数表示。同一图像采用不同编码规则生成不同类型的文件，如BMP、JPEG、PNG等，所需要的存储空间也不一样。', 4, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'N', 6, 120, 1927, '683484', '2026-03-12 10:09:17', '', NULL);
INSERT INTO `biz_question` VALUES (174, 'practical', '完成八下第3课作业', 8, '1', 3, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/12/第3.4课  作业_20260312153932A626.docx', '/profile/upload/2026/03/12/第3.4课  作业_20260312153932A626.pdf', 'success', 'N', NULL, NULL, 1906, '657430', '2026-03-12 15:40:18', '', NULL);
INSERT INTO `biz_question` VALUES (175, 'typing', '随互联网实现了从计算机互联到人类互联的跨越，而物联网是在其基础上发展的物物相连的网络，简称 IoT，是传感技术的综合应用。1991 年凯文・艾什顿首次提出物联网概念，1999 年提出万物皆可互联。2005 年 ITU 发布物联网相关报告，2009 年我国提出 “感知中国”，将其纳入国家战略。物联网应用覆盖智慧城市、智慧医疗等诸多领域，学习中需明晰互联网与物联网的异同，梳理其发展标志性事件，理解物联网产生的技术背景与应用价值。', 7, '1', 1, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 206, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (176, 'typing', '物联网是物理与数字世界的桥梁，具备全面感知、可靠传递、智能处理三大核心特征，分别依靠感知设备获取数据、通信网络传输数据、智能技术分析处理数据。其架构分为四层，感知层负责信息采集，如同人体感官；网络层通过各类通信技术传递信息，类似神经网络；平台层依托云平台处理数据，堪比大脑；应用层对接用户实现智能应用。学习中要区分物联网与互联网的差异，能罗列物联网设备并对应其所属架构层，绘制物联网应用的架构示意图。', 7, '1', 2, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 5, 200, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (177, 'typing', '物联网深度渗透生活各领域，推动生活方式向智能化变革，核心应用包含智能家居、智慧交通、智慧物流、智慧农业。智能家居可实现家电远程控制与家居智能化管理，营造便捷居住环境；智慧交通通过车辆监控提升通行效率，车联网是其重要组成部分；智慧物流依托自动分拣、无人机快递实现配送智能化；智慧农业利用传感器实现自动灌溉、养殖监测，保障农产品产量与品质。学习中要结合生活实例，感受物联网对工作、学习和生活的影响，用思维导图梳理其生活应用场景。', 7, '1', 3, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 212, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (178, 'typing', '物联网与大数据、人工智能、云计算深度融合，成为技术发展的重要趋势。大数据具有数量大、速度快、类型多、价值密度低的特征，物联网为其提供海量多元数据，大数据技术则助力物联网数据处理。物联网为人工智能提供训练数据，人工智能推动物联网智能化，催生 AIoT 概念。云计算为物联网海量数据处理提供算力支持，边缘计算则解决了物联网终端低时延、高稳定的需求。物联网未来将向规模化、协同化、智能化发展，学习中要畅想技术融合的应用场景，理解其对社会发展的深远影响。', 7, '1', 4, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 221, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (179, 'typing', '感知层是物联网信息采集的核心，通过传感、识别、定位技术实现物理与数字世界的融合。传感技术以传感器为核心，是物联网的 “感觉器官”，能将物理量转换为电信号。识别技术包含条码、二维码、RFID 技术，条形码和二维码通过光电设备识别信息，RFID 是无接触式自动识别技术，分无源、有源、半有源三类，在 ETC、产品溯源等领域广泛应用。学习中要掌握各类感知识别技术的原理，举例说明其生活应用，理解感知层多样化的信息采集方式。', 7, '1', 5, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 204, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (180, 'typing', '传感器是物联网感知层的核心部件，其检测元件能将温度、湿度等物理量转换为电信号。传感器分类多样，按工作原理分电阻、光电等类型，按功能可类比人类五官，如光敏对应视觉、声敏对应听觉，按被测物理量分压力、加速度等类型，按输出信号分数字和模拟信号。智能手机集成了多种传感器，如图像、磁场、指纹识别传感器，丰富了智能体验。智能家居中也广泛应用传感器，如光敏传感器用于智能小夜灯，压力传感器用于扫地机器人避障。学习中要识别常见传感器，了解其工作原理与应用场景。', 7, '1', 6, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 223, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (181, 'typing', '传感器的应用需根据物理环境、物体特征和应用需求合理选择，测量对象和精度要求不同，所选传感器也不同，如测空气和液体温度需用不同的温度传感器。传感器应用场景广泛，可实现声控灯、人体感应灯等简易设计，还能通过控制板和程序实现数据实时采集，如用 Python 的 while 循环获取环境声音数据。在智能农场、智慧交通、智能家居等领域，传感器各司其职，成为物联网数据采集的关键。学习中要能根据需求选择传感器，体验传感器数据的获取与串口呈现方式，掌握其实际应用方法。', 7, '1', 7, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 224, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (182, 'typing', '物联网网络层的短距离无线传输技术应用广泛，核心包含蓝牙、Wi-Fi、NFC 等。蓝牙是近距离通信技术，设备需配对后通信，一个主设备可连接多个从设备；Wi-Fi 基于 802.11 标准，连接速度快、覆盖广，是家庭物联网的主流选择；NFC 由 RFID 演变而来，可实现非接触式通信，用于刷卡支付、打印等场景。物联网传感设备可配置通信模块实现联网，通过控制板编写代码可完成 Wi-Fi 连接，实现数据传输。学习中要掌握常见无线通信技术的特点，分析其传输速度、通信距离等参数，实践物联设备的联网方法。', 7, '1', 8, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 239, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (183, 'typing', '物联网通信基于互联网协议，同时拥有专属协议，分为传输和通信协议两类，常用的有 HTTP、MQTT、CoAP 等。MQTT 协议基于 TCP/IP，专为物联网设计，相比 HTTP，其协议开销低、功耗小，适配低延迟、带宽有限的网络。MQTT 是发布 / 订阅型协议，由中介、发布者、订阅者构成，发布者发送主题消息至中介，中介将消息推送给订阅该主题的订阅者，实现一对多通信。学习中要对比 MQTT 与 HTTP 的性能差异，理解 MQTT 订阅模型的工作原理，实践利用 MQTT 协议实现物联网数据通信。', 7, '1', 9, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 233, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (184, 'typing', '物联系统是物联网技术支撑的信息系统，物联系统原型是其原始形态，用于检验、测试系统功能，包含子系统原型和功能原型。搭建需经历前期分析、架构设计、硬件搭建、软件开发、系统测试和原型验证阶段。以 “校园农场” 物联系统原型为例，可设计自动浇灌、智能光照等子系统原型，根据功能需求选择硬件并搭建，再对各功能原型进行验证。学习中要理解物联系统与原型的异同，掌握原型搭建的基本流程，动手搭建并验证简单的物联子系统原型。', 7, '1', 10, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 201, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (185, 'typing', '物联网数据获取方式多样化，依托感知层的识别、传感、定位技术采集物理世界信息，如 “校园农场” 原型通过水分、光敏等传感器采集对应数据。数据的发送和接收基于 TCP/IP、MQTT 等协议，感知层采集的数据经物联网网关，通过网络层传输至平台层服务器，服务器可作为订阅者接收网关发布的主题消息。数据发布的时间和频次需根据实际需求设定，如环境监测数据需合理把控发布间隔。学习中要掌握数据获取的多种方式，理解数据传输的原理，绘制数据采集、传输和接收的过程示意图。', 7, '1', 11, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 223, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (186, 'typing', '物联网数据最终汇集于平台层服务器，服务器具备收发、处理、存储数据的核心功能。数据处理分为批处理和流处理，批处理先存储后定时批量处理，节约资源；流处理接收后立即处理，能实时响应。数据使用前需清洗过滤，去除噪声和异常值，服务器处理数据后通过预设控制逻辑和阈值做出反馈，以指令形式控制执行器。如 “自动浇灌” 原型中，服务器根据土壤湿度阈值控制水泵启停，该逻辑可通过 Python 的 if-else 分支语句实现。学习中要掌握数据汇集处理方式，体会数据处理与反馈的过程。', 7, '1', 12, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 227, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (187, 'typing', '物联网的控制与反馈是传感器感知信息，控制器处理后发送信号给执行器，执行器作用于受控对象，同时对象状态反馈给控制器的闭环过程。控制形式分为手动控制和自动控制，手动控制由人通过终端远程操纵设备，自动控制则按预设规则分析数据并执行控制行为。以 “智能水位控制” 原型为例，超声波传感器监测水位，控制器根据阈值向执行器发送指令，实现水泵的自动启停，可通过控制板和 Python 程序实现该功能。学习中要分析生活中的智能控制实例，掌握控制与反馈的实现过程，编写简单的控制程序。', 7, '1', 13, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 229, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (188, 'typing', '物联系统原型搭建需遵循需求分析、方案设计、硬件搭建、软件开发等流程，程序编写是软件开发的核心。以 “校园农场” 原型为例，其包含四个子系统原型，分接两块控制板，程序编写需按子系统功能设计逻辑，通过读取传感器数据、对比阈值、控制执行器实现功能，如自动浇灌原型根据土壤湿度控制水泵。同时可利用 MQTT 协议将传感器数据发布至云端服务器，实现数据汇集。学习中要分解物联系统的功能需求，掌握程序编写的基本逻辑，为简单的物联子系统原型编写程序，并实现数据的云端发布。', 7, '1', 14, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 225, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (189, 'typing', '物联系统原型硬件搭建和程序编写完成后，需经过调试、运行和联调才能投入使用。硬件调试可分块验证子系统功能，通过观察法、元件替换法检测硬件连接和元件状态。软件调试需检查代码的语法、逻辑错误，通过分单元测试、数据分析法验证程序逻辑。联调需关注系统运行的正确性和稳定性，持续监测系统状态，排查数据交互、硬件工作中的问题。调试过程中会经历发现问题、解决问题的螺旋上升过程，推动系统原型的迭代完善。学习中要掌握软硬件调试的方法，完成系统联调，记录调试中的问题与解决策略。', 7, '1', 15, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 6, 229, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (190, 'typing', '物联网简称 IoT，是物物相连的互联网络，是传感技术的综合应用，1991 年由凯文・艾什顿首次提出。互联网实现了从计算机互联到人类互联的跨越，物联网则在此基础上实现人与物、物与物的连接。2009 年我国提出 “感知中国”，将物联网发展纳入国家战略。其应用覆盖智慧城市、智慧医疗等领域，学习中需梳理其发展历程，明晰与互联网的异同。', 8, '1', 1, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 160, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (191, 'typing', '物联网是物理与数字世界的桥梁，有全面感知、可靠传递、智能处理三大核心特征，分别实现数据获取、传输与智能分析决策。其架构分为四层，感知层负责信息采集，网络层传递信息，平台层依托云平台处理数据，应用层实现各行业智能应用。学习中要能区分物联网设备所属架构层，理解其特征与架构的关联，绘制物联网应用架构示意图。', 8, '1', 2, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 151, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (192, 'typing', '物联网深度融入生活，核心应用包括智能家居、智慧交通、智慧物流和智慧农业。智能家居可远程控制家电，打造智能居住环境；智慧交通依托车辆监控提升通行效率，车联网是重要组成；智慧物流通过自动分拣、无人机快递实现配送智能；智慧农业利用传感器实现自动灌溉、养殖监测。物联网推动生活向智能化变革，需结合实例感受其对生活的影响。', 8, '1', 3, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 156, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (193, 'typing', '物联网与大数据、人工智能、云计算深度融合。大数据具有量大、速快、类型多、价值密度低的特征，物联网为其提供海量数据，大数据技术助力物联网数据处理。物联网为人工智能提供训练数据，二者融合催生 AIoT。云计算为物联网提供算力，边缘计算解决其低时延需求。物联网未来将向规模化、协同化、智能化发展，深刻影响人类社会。', 8, '1', 4, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 153, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (194, 'typing', '物联网感知层通过传感、识别、定位技术采集信息，实现物理与数字世界融合。传感技术以传感器为核心，将物理量转换为电信号。识别技术包含条码、二维码和 RFID 技术，前两者通过光电设备识别，RFID 是非接触式自动识别技术，分无源、有源、半有源三类，在 ETC、产品溯源等领域广泛应用，需掌握各类技术的应用场景。', 8, '1', 5, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 149, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (195, 'typing', '传感器是物联网感知层核心，检测元件能将温度、湿度等物理量转换为电信号。其分类多样，按工作原理分电阻、光电等，按功能可类比人类五官，如光敏对应视觉、声敏对应听觉，按输出信号分数字和模拟信号。智能手机和智能家居中集成多种传感器，如智能小夜灯的光敏传感器、扫地机器人的压力传感器，需了解其原理与应用。', 8, '1', 6, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 147, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (196, 'typing', '传感器需根据应用场景、测量对象和精度需求合理选择，测空气和液体温度需用不同的温度传感器。其应用广泛，可实现声控灯、人体感应灯等设计，还能通过控制板和 Python 程序实时采集数据，如用 while 循环获取环境声音数据，通过串口调试工具查看数据。学习中要能根据需求选传感器，体验数据获取与呈现方式。', 8, '1', 7, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 146, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (197, 'typing', '物联网网络层短距离无线通信技术主要有蓝牙、Wi-Fi、NFC。蓝牙是近距离技术，设备需配对，一个主设备可连接多个从设备；Wi-Fi 基于 802.11 标准，连接快、覆盖广，是家庭物联网主流；NFC 由 RFID 演变而来，用于刷卡支付、打印等。传感设备配置通信模块可联网，通过控制板编写代码能实现 Wi-Fi 连接，完成数据传输。', 8, '1', 8, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 158, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (198, 'typing', '物联网通信基于 HTTP、TCP/IP 等互联网协议，还有 MQTT、CoAP 等专用协议。MQTT 协议基于 TCP/IP，协议开销低、功耗小，适配低带宽、高延迟网络，是发布 / 订阅型协议，由中介、发布者、订阅者构成，实现一对多异步通信。发布者发送主题消息至中介，中介推送给订阅者，相比 HTTP，更适合物联网设备的通信需求。', 8, '1', 9, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 156, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (199, 'typing', '物联系统是物联网技术支撑的信息系统，原型是其原始形态，用于检验、测试系统功能，含子系统原型和功能原型。搭建需经前期分析、架构设计、硬件搭建、软件开发、测试验证等阶段。以校园农场原型为例，可设计自动浇灌、智能光照等子系统，根据功能需求选硬件搭建，再对各功能原型进行验证，理解原型与实际系统的异同。', 8, '1', 10, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 147, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (200, 'typing', '物联网通过感知层的识别、传感、定位技术多样化获取数据，校园农场原型通过水分、光敏等传感器采集对应数据。数据发送和接收基于 MQTT、TCP/IP 等协议，感知层数据经物联网网关，通过网络层传输至平台层服务器，服务器作为订阅者接收网关发布的主题消息。需掌握数据传输原理，合理设定数据发布的时间和频次。', 8, '1', 11, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 147, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (201, 'typing', '物联网数据最终汇集于平台层服务器，服务器具备收发、处理、存储数据三大功能。数据处理分批处理和流处理，批处理先存储后定时处理，节约资源；流处理实时处理，响应迅速。数据使用前需清洗过滤，服务器根据预设阈值和控制逻辑做出反馈，如自动浇灌原型中，通过 Python 的 if-else 语句根据土壤湿度控制水泵启停。', 8, '1', 12, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 150, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (202, 'typing', '物联网控制与反馈是闭环过程，传感器感知信息，控制器处理后发信号给执行器，执行器作用于受控对象，对象状态再反馈给控制器。控制形式分手动和自动，手动控制通过终端远程操纵设备，自动控制按预设规则分析数据并执行操作。以智能水位控制原型为例，可通过控制板和程序，根据超声波传感器数据实现水泵的自动启停。', 8, '1', 13, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 146, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (203, 'typing', '物联系统原型搭建需经需求分析、硬件搭建、软件开发等流程，程序编写是软件开发核心。校园农场原型含四个子系统，分接两块控制板，程序编写需读取传感器数据、对比阈值、控制执行器实现功能。同时可利用 MQTT 协议将传感器数据发布至云端服务器，实现数据汇集，需分解功能需求，掌握程序编写的基本逻辑。', 8, '1', 14, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 142, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (204, 'typing', '物联系统原型完成硬件搭建和程序编写后，需经硬件调试、软件调试和联调。硬件调试可分块验证子系统，用观察法、元件替换法检测连接；软件调试检查代码错误，用数据分析法验证逻辑；联调关注系统运行的正确性和稳定性，持续监测并排查故障。调试过程是发现并解决问题的过程，推动系统原型不断迭代完善。', 8, '1', 15, '', '', '', '', '', '', NULL, NULL, NULL, 'N', 4, 140, 1893, '698051', '2026-03-12 15:48:08', '', NULL);
INSERT INTO `biz_question` VALUES (205, 'typing', '清晨，阳光照进校园。教室里，同学们端正地坐在座位上，认真听老师讲课。大家积极举手发言，声音响亮又清楚。下课了，操场上立刻热闹起来。有的同学跑步，有的同学打球，还有的同学在做游戏，到处都是欢声笑语。', 4, '1', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'N', 5, 98, 1907, '680894', '2026-03-13 08:47:21', '', NULL);
