INSERT INTO `biz_question` VALUES (442, 'choice', '手机端智能家居控制 APP，属于物联网架构的（  ）', 7, '1', 3, '感知层', '网络层', '平台层', '应用层', 'D', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:04:29', '', NULL);
INSERT INTO `biz_question` VALUES (443, 'judgment', '物联网标准架构分为感知层、网络层、平台层、应用层四层。', 7, '1', 3, NULL, NULL, NULL, NULL, 'T', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:06:34', '', NULL);
INSERT INTO `biz_question` VALUES (444, 'judgment', '网络层的核心功能是采集环境、物体的各类基础数据。', 7, '1', 3, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:07:12', '', NULL);
INSERT INTO `biz_question` VALUES (445, 'judgment', '智能空调、智能灯具都是物联网在智能家居中的典型应用。', 7, '1', 3, NULL, NULL, NULL, NULL, 'T', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:07:34', '', NULL);
INSERT INTO `biz_question` VALUES (446, 'judgment', '物联网仅连接物品，和人的日常生产生活没有关联。', 7, '1', 3, NULL, NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:08:01', '', NULL);
INSERT INTO `biz_question` VALUES (447, 'judgment', '全面感知依托传感器、摄像头等设备，实现物理信息的采集。', 7, '1', 3, NULL, NULL, NULL, NULL, 'T', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:08:32', '', NULL);
INSERT INTO `biz_question` VALUES (448, 'choice', '以下哪个场景应用了物联网技术？', 7, '1', 3, '小明使用手机闹钟每天定时起床，与以往相比生活更加规律。', '小红家中的智能温控系统根据室内外温差自动调节室内温度，使居住环境更加舒适节能。', '李老师在课堂上使用PPT讲解知识，与以往板书教学相比提高了教学效率。', '小刚通过手机APP查看天气预报，提前准备出行衣物。', 'B', NULL, NULL, NULL, NULL, 'Y', NULL, NULL, 1587, '960250', '2026-03-17 16:10:03', '', NULL);
INSERT INTO `biz_question` VALUES (449, 'choice', '假设你参与了一个关于“智慧城市”的项目，你认为物联网技术有可能在以下哪个领域发挥重要作用？', 7, '1', 3, '交通领域，通过智能交通系统，可以实时收集和分析交通流量，实现信号灯的智能调控。', '文学创作领域，辅助作者进行散文、诗歌的写作。', '手工制作领域，指导人们进行陶艺、编织等手工创作。', '书法绘画领域，帮助人们练习毛笔字和国画。', 'A', NULL, NULL, NULL, NULL, 'N', NULL, NULL, 1587, '960250', '2026-03-17 16:15:25', '', NULL);
INSERT INTO `biz_question` VALUES (450, 'practical', '控制系统中的数据', 6, '1', 5, NULL, NULL, NULL, NULL, NULL, NULL, '/profile/upload/2026/03/18/学习单_20260318121429A346.docx', '/profile/upload/2026/03/18/学习单_20260318121429A346.pdf', 'success', 'Y', NULL, NULL, 104, '19157727791', '2026-03-18 12:14:41', '', NULL);
INSERT INTO `biz_question` VALUES (451, 'typing', '控制系统的运行离不开数据，其形态主要分为连续量和开关量。大小随时间连续变化的数据称为连续量，用来控制设备开与关等只有两种状态的数据称为开关量。数据在控制系统中不断转换，它是系统准确运行的关键媒介。数据能够真实反映控制对象的运行状况。', 6, '1', 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 116, 104, '19157727791', '2026-03-18 12:18:34', '', NULL);
INSERT INTO `biz_question` VALUES (452, 'typing', '信息科技的发展为人类创造了一个全新的数字化生活环境。数字化后的数据可以更方便地在数字设备中存储、处理和传输。将复杂多样的信息转化为计算机可以识别并处理的数据，这个过程就是数字化。数字技术的广泛应用极大地改善并丰富了人们解决问题的方法。例如：数字图书馆让人们足不出户就可以获取所需的学习资源；公共场所的数字摄像设备可及时捕捉安保数据，有力地保障社会的安全。随着数字技术在各领域的普及，人们迈入数字化生活时代。如人们可以使用智能手机、平板电脑等数字设备，拍照、录音和观看视频，便捷地参与在线学习、在线协作、在线零售、在线政务等活动。', 4, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 14, 264, 1881, '683927', '2026-03-18 12:33:20', '', NULL);
INSERT INTO `biz_question` VALUES (453, 'typing', '系统是由多个要素以一定结构联结而成且具有特定功能的有机整体。系统虽然各不相同，但它们都具有整体性和目的性。在现实世界中，系统具有普遍性和多样性。形形色色的系统互相交织，集合在一起，构成了丰富多彩的世界。 ', 5, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 6, 101, 1881, '683927', '2026-03-18 13:17:47', '', NULL);
INSERT INTO `biz_question` VALUES (454, 'typing', '生活中，我们身边藏着许多神奇的自动控制系统。例如，智能家居中的自动感应灯，当天黑有人经过时，它能自动亮起；当人离开后，它又会自动熄灭，非常节能。在农业领域，智慧农场利用计算机技术，通过土壤湿度传感器采集数据。当土壤干燥时，计算机会指令灌溉系统自动喷水；湿度达标后则自动停止。', 6, '1', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Y', 7, 137, 1881, '683927', '2026-03-18 13:32:33', '', NULL);
