INSERT INTO `biz_student_answer` VALUES (3480, 878, 30, 102, '打铁花是中国古代匠师们在铸造器皿过程中发现的一种民俗文化表演技艺，始于北宋，盛于明清，至今已有千余年历史。打铁花多流传于黄河中下游，以河南、山西最为流行，开封打铁花更被誉为黄河流域十大民间艺术之首。打铁花表演时，在一处空旷场地搭出六米高的双层花棚，', 0, 9, 297, '2026-01-20 15:06:56', 25, 100.00, 47.00, NULL, NULL);
