INSERT INTO `biz_student_answer` VALUES (5137, 296, 23, 111, '核心知识点：控制形态主要分为人工干预控制和自动控制。人工干预控制需人直接或全程干预，如手动控制电灯开关；自动控制无需人参与即可实现目标，如感应灯自动亮灭。两者核心区别在于，输出量能否返回输入端与输入量比较，形成闭合环路。', 1, 30, 215, '2026-01-21 12:51:34', 31, 100.00, 100.00, NULL, NULL);
