INSERT INTO `biz_student_answer` VALUES (6150, 484, 32, 79, '1956 年美国达特茅斯会议正式提出 “人工智能（AI）” 概念，该年被视为人工智能元年。英国数学家阿兰・图灵在《计算机器与智能》中提出 “图灵测试”，以提问者判断失误率≥30% 作为机器具备人类智能的标准。人工智能发展并非一帆风顺，经历了三起两落的历程，不同阶段核心研究方向从符号推理逐步拓展。', 1, 50, 4, '2026-01-26 10:53:25', 2220, 100.00, 100.00, NULL, NULL);
