INSERT INTO `biz_student_answer` VALUES (15048, 3195, 60, 179, '感知层是物联网信息采集的核心，通过传感、识别、定位技术实现物理与数字世界的融合。传感技术以传感器为核心，是物联网的 “感觉器官”，能将物理量转换为电信号。识别技术包含条码、二维码、RFID 技术，条形码和二维码通过光电设备识别信息，RFID 是无接触式自动识别技术，分无源、有源、半有源三类，在 ETC、产品溯源等领域广泛应用。学习中要掌握各类感知识别技术的原理，举例说明其生活应用，理解感知层多样化的信息采集方式。', 1, 10, 279, '2026-03-17 14:52:50', 45, 100.00, 100.00, NULL, NULL);
