INSERT INTO `sys_oper_log` VALUES (481, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"3班\",\"7班\"],\"grade\":6,\"lessonId\":23,\"lessonNum\":1,\"lessonTitle\":\"自动控制系统\",\"params\":{},\"questions\":[{\"lessonId\":23,\"orderNum\":1,\"params\":{},\"questionContent\":\"第1课自动控制系统介绍了自动控制系统能在无人干预下自动实现目标，如空调、自动灌溉等。系统通常由控制器、执行器和被控对象组成，并常借助传感器获取反馈信息。计算机在其中起关键作用：通过指令实现更精准、复杂和智能的控制，提升系统灵活性与效率。计算机能实现更智能的控制。\",\"questionId\":54,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":131},{\"filePath\":\"/profile/upload/2026/01/12/学习单_20260112125728A001.docx\",\"lessonId\":23,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/12/学习单_20260112125728A001.pdf\",\"questionContent\":\"定时灌溉和智慧农场系统的区别\",\"questionId\":55,\"questionScore\":30,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":12,\"itemName\":\"答案是否正常\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":55}]},{\"answer\":\"C\",\"lessonId\":23,\"optionA\":\"顺序结构\",\"optionB\":\"分支结构\",\"optionC\":\"循环结构\",\"optionD\":\"选择结构\",\"orderNum\":3,\"params\":{},\"questionContent\":\"猜数字游戏中，用于反复让用户输入的结构是\",\"questionId\":58,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":23,\"optionA\":\"排序法\",\"optionB\":\"枚举法\",\"optionC\":\"加密法\",\"optionD\":\"压缩法\",\"orderNum\":4,\"params\":{},\"questionContent\":\"在“鸡兔同笼”问题中，常用的算法思想是？\",\"questionId\":57,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":23,\"optionA\":\"随意性\",\"optionB\":\"有限性\",\"optionC\":\"娱乐性\",\"optionD\":\"模糊性\",\"orderNum\":5,\"params\":{},\"questionContent\":\"下列哪一项属于算法的基本特征\",\"questionId\":56,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"lessonId\":23,\"optionA\":\"北京\",\"optionB\":\"上海\",\"option