INSERT INTO `sys_oper_log` VALUES (591, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"4班\",\"6班\",\"7班\",\"8班\"],\"grade\":8,\"lessonId\":25,\"lessonNum\":1,\"lessonTitle\":\"1-走进人工智能\",\"params\":{},\"questions\":[{\"lessonId\":25,\"orderNum\":1,\"params\":{},\"questionContent\":\"1956 年美国达特茅斯会议正式提出 “人工智能（AI）” 概念，该年被视为人工智能元年。英国数学家阿兰・图灵在《计算机器与智能》中提出 “图灵测试”，以提问者判断失误率≥30% 作为机器具备人类智能的标准。人工智能发展并非一帆风顺，经历了三起两落的历程，不同阶段核心研究方向从符号推理逐步拓展。\",\"questionId\":79,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":4,\"wordCount\":143},{\"filePath\":\"/profile/upload/2026/01/19/课后作业_20260119151609A133.docx\",\"lessonId\":25,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/19/课后作业_20260119151609A133.pdf\",\"questionContent\":\"操作题\",\"questionId\":81,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":14,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":81}]},{\"answer\":\"A\",\"lessonId\":25,\"optionA\":\"1956\",\"optionB\":\"1943\",\"optionC\":\"1978\",\"optionD\":\"1999\",\"orderNum\":3,\"params\":{},\"questionContent\":\"被普遍认为 “人工智能元年” 的是哪一年\",\"questionId\":80,\"questionScore\":20,\"questionType\":\"choice\",\"scoringItems\":[]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"4班\",\"6班\",\"7班\",\"8班\"],\"grade\":8,\"lessonId\":25,\"lessonNum\":1,\"lessonTitle\":\"1-走进人工智能\",\"params\":{},\"questions\":[{\"lessonId\":25,\"orderNum\":1,\"params\":{},\"questionContent\":\"1956 年美国达特茅斯会议正式提出 “人工智能（AI）” 概念，该年被视为人工智能元年。英国数学家阿兰・图灵在《计算机器与智能》中提出 “图灵测试”，以提问者判断失误率≥30% 作为机器具备人类智能的标准。人工智能发展并非一帆风顺，经历了三起两落的历程，不同阶段核心研究方向从符号推理逐步拓展。\",\"questionId\":79,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":4,\"wordCount\":143},{\"filePath\":\"/profile/upload/2026/01/19/课后作业_20260119151609A133.docx\",\"lessonId\":25,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/19/课后作业_20260119151609A133.pdf\",\"questionContent\":\"操作题\",\"questionId\":81,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":14,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":81}]},{\"answer\":\"A\",\"lessonId\":25,\"optionA\":\"1956\",\"optionB\":\"1943\",\"optionC\":\"1978\",\"optionD\":\"1999\",\"orderNum\":3,\"params\":{},\"questionContent\":\"被普遍认为 “人工智能元年” 的是哪一年\",\"questionId\":80,\"questionScore\":20,\"questionType\":\"choice\",\"scoringItems\":[]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"0\",\"shuffleMode\":0}}', 0, NULL, '2026-03-03 09:10:43', 53);
