INSERT INTO `sys_oper_log` VALUES (593, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"1班\"],\"grade\":8,\"lessonId\":31,\"lessonNum\":1,\"lessonTitle\":\"0-考试\",\"params\":{},\"questions\":[{\"answer\":\"\",\"lessonId\":31,\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"互联网应用极大改变了我们的生活方式，从在线学习到电子支付，数据早已无处不在。网页是互联网数据呈现的重要载体，而超文本标记语言HTML则是制作网页的基石。在HTML代码中，标签通常成对出现，例如BODY标签定义了网页的主体内容，IMG标签用于插入图像。我们在享受便捷的同时，绝不能忽视网络安全隐患。为了保护个人隐私和数据资产，我们需要养成定期备份数据的习惯。\",\"questionId\":110,\"questionScore\":35,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":4,\"wordCount\":178},{\"filePath\":\"/profile/upload/2026/01/20/课后作业_20260120130453A040.docx\",\"lessonId\":31,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/20/课后作业_20260120130453A040.pdf\",\"questionContent\":\"操作题\",\"questionId\":112,\"questionScore\":30,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":16,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":112}]},{\"answer\":\"C\",\"lessonId\":31,\"optionA\":\"<body>...</body>\",\"optionB\":\"<p>...</p>\",\"optionC\":\"<title>...</title>\",\"optionD\":\"<h1>...</h1>\",\"orderNum\":3,\"params\":{},\"questionContent\":\"如果要在网页标题栏显示“期末考试”，代码应写在哪个标签之间？\",\"questionId\":108,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":31,\"optionA\":\"<head>\",\"optionB\":\"<body>\",\"optionC\":\"<title>\",\"optionD\":\"<html>\",\"orderNum\":4,\"params\":{},\"questionContent\":\"在HTML网页代码中，用于定义网页“主体内容”的标签是？\",\"questionId\":104,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"lessonId\":31,\"optionA\":\"<img>\",\"optionB\":\"<pic>\",\"optionC\":\"<image>\",\"optionD\":\"<src>\",\"orderNum\":5,\"params\":{},\"questionContent\":\"想要在网页中插入一张图片，应该使用以下哪个标签？\",\"questionId\":105,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"lessonId\":31,\"optionA\":\"HTML标签通常是成对出现的\",\"optionB\":\"<br>标签用于换行，它没有结束标签\",\"optionC\":\"HTML是不区分大小写的\",\"optionD\":\"<html>标签表示网页的结束\",\"orderNum\":6,\"params\":{},\"questionContent\":\"下列关于HTML标签的说法，错误的是？\",\"questionId\":106,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\"],\"grade\":8,\"lessonId\":31,\"lessonNum\":1,\"lessonTitle\":\"0-考试\",\"params\":{},\"questions\":[{\"lessonId\":31,\"orderNum\":1,\"params\":{},\"questionContent\":\"互联网应用极大改变了我们的生活方式，从在线学习到电子支付，数据早已无处不在。网页是互联网数据呈现的重要载体，而超文本标记语言HTML则是制作网页的基石。在HTML代码中，标签通常成对出现，例如BODY标签定义了网页的主体内容，IMG标签用于插入图像。我们在享受便捷的同时，绝不能忽视网络安全隐患。为了保护个人隐私和数据资产，我们需要养成定期备份数据的习惯。\",\"questionId\":110,\"questionScore\":35,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":4,\"wordCount\":178},{\"filePath\":\"/profile/upload/2026/01/20/课后作业_20260120130453A040.docx\",\"lessonId\":31,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/20/课后作业_20260120130453A040.pdf\",\"questionContent\":\"操作题\",\"questionId\":112,\"questionScore\":30,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":16,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":112}]},{\"answer\":\"C\",\"lessonId\":31,\"optionA\":\"<body>...</body>\",\"optionB\":\"<p>...</p>\",\"optionC\":\"<title>...</title>\",\"optionD\":\"<h1>...</h1>\",\"orderNum\":3,\"params\":{},\"questionContent\":\"如果要在网页标题栏显示“期末考试”，代码应写在哪个标签之间？\",\"questionId\":108,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":31,\"optionA\":\"<head>\",\"optionB\":\"<body>\",\"optionC\":\"<title>\",\"optionD\":\"<html>\",\"orderNum\":4,\"params\":{},\"questionContent\":\"在HTML网页代码中，用于定义网页“主体内容”的标签是？\",\"questionId\":104,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"lessonId\":31,\"optionA\":\"<img>\",\"optionB\":\"<pic>\",\"optionC\":\"<image>\",\"optionD\":\"<src>\",\"orderNum\":5,\"params\":{},\"questionContent\":\"想要在网页中插入一张图片，应该使用以下哪个标签？\",\"questionId\":105,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"lessonId\":31,\"optionA\":\"HTML标签通常是成对出现的\",\"optionB\":\"<br>标签用于换行，它没有结束标签\",\"optionC\":\"HTML是不区分大小写的\",\"optionD\":\"<html>标签表示网页的结束\",\"orderNum\":6,\"params\":{},\"questionContent\":\"下列关于HTML标签的说法，错误的是？\",\"questionId\":106,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"lessonId\":31,\"optionA\":\".txt\",\"', 0, NULL, '2026-03-03 09:12:36', 21);
INSERT INTO `sys_oper_log` VALUES (594, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大徐小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-03-03 09:14:45\",\"creatorId\":104,\"filePath\":\"/profile/upload/2026/03/03/第2课人工智能应用作业_20260303091433A001.docx\",\"grade\":8,\"isPublic\":\"Y\",\"lessonNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/03/第2课人工智能应用作业_20260303091433A001.pdf\",\"previewStatus\":\"pending\",\"questionContent\":\"人工智能应用作业\",\"questionId\":120,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":20,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":120}],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-03 09:14:45', 36);
INSERT INTO `sys_oper_log` VALUES (595, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大徐小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-03-03 09:22:19\",\"creatorId\":104,\"grade\":8,\"isPublic\":\"Y\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。\",\"questionId\":121,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":191}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-03 09:22:19', 12);
