INSERT INTO `sys_oper_log` VALUES (616, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大徐小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"2班\"],\"grade\":8,\"lessonId\":33,\"lessonNum\":2,\"lessonTitle\":\"2-人工智能应用\",\"params\":{},\"questions\":[{\"lessonId\":33,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。\",\"questionId\":121,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":191},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/21/考试操作题_20260121124339A213.pdf\",\"questionContent\":\"六年级\",\"questionId\":118,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-01-21 12:43:52\",\"itemId\":17,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":118,\"updateTime\":\"2026-01-21 12:43:52\"}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"2班\"],\"grade\":8,\"lessonId\":33,\"lessonNum\":2,\"lessonTitle\":\"2-人工智能应用\",\"params\":{},\"questions\":[{\"lessonId\":33,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。\",\"questionId\":121,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":191},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/01/21/考试操作题_20260121124339A213.pdf\",\"questionContent\":\"六年级\",\"questionId\":118,\"questionScore\":40,\"questionType\":\"practi