INSERT INTO `sys_oper_log` VALUES (637, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '675077', '塔山中学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"675077\",\"createTime\":\"2026-03-05 09:28:13\",\"creatorId\":896,\"grade\":7,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"0\",\"typingDuration\":5,\"wordCount\":183}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-05 09:28:13', 10);
