INSERT INTO `sys_oper_log` VALUES (726, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-03-10 10:46:16\",\"creatorId\":104,\"grade\":8,\"isPublic\":\"Y\",\"lessonNum\":4,\"params\":{},\"questionContent\":\"人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。\",\"questionId\":168,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":179}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-10 10:46:16', 10);
