INSERT INTO `sys_oper_log` VALUES (777, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"2班\"],\"grade\":8,\"lessonId\":34,\"lessonNum\":1,\"lessonTitle\":\"3-人工智能技术基础课后练习\",\"params\":{},\"questions\":[{\"lessonId\":34,\"orderNum\":1,\"params\":{},\"questionContent\":\"数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能\",\"questionId\":122,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":219},{\"filePath\":\"/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.docx\",\"lessonId\":34,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.pdf\",\"questionContent\":\"人工智能基础课后练习\",\"questionId\":131,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":26,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":131}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"2班\"],\"grade\":8,\"lessonId\":34,\"lessonNum\":1,\"lessonTitle\":\"3-人工智能技术基础课后练习\",\"params\":{},\"questions\":[{\"lessonId\":34,\"orderNum\":1,\"params\":{},\"questionContent\":\"数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能\",\"questionId\":122,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":219},{\"filePath\":\"/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.docx\",\"lessonId\":34,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/09/八下第3课作业_20260309104049A181.pdf\",\"questionContent\":\"人工智能基础课后练习\",\"questionId\":131,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":26,\"itemName\":\"答案是否正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":131}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-11 12:01:09', 17);
INSERT INTO `sys_oper_log` VALUES (778, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"7班\",\"6班\"],\"grade\":8,\"lessonId\":33,\"lessonNum\":2,\"lessonTitle\":\"2-人工智能应用\",\"params\":{},\"questions\":[{\"lessonId\":33,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。\",\"questionId\":121,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":191},{\"filePath\":\"/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.docx\",\"lessonId\":33,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.pdf\",\"questionContent\":\"人工智能应用课后练习\",\"questionId\":127,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":24,\"itemName\":\"答案\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":127}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"7班\",\"6班\"],\"grade\":8,\"lessonId\":33,\"lessonNum\":2,\"lessonTitle\":\"2-人工智能应用\",\"params\":{},\"questions\":[{\"lessonId\":33,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能应用的表现形式大致可分为能听、能说、能看、能写、会思考、会学习和会行动等方面 。本课核心掌握三大应用：一是机器翻译，它以自然语言理解为核心，结合语言学知识实现精准翻译 。二是无人驾驶，它通过感知系统识别环境、决策系统规划导航、执行系统控制车辆运行，三系统协同合作实现自动行驶 。三是人机博弈，运用计算机技术与博弈思想，结合深度学习等技术，使机器能像人类一样从事高度智能的对策活动 。\",\"questionId\":121,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":191},{\"filePath\":\"/profile/upload/2026/03/04/第2课人工智能应用作业1_20260304091828A001.docx\",\"lessonId\":33,\"orderNum\":2,\"params\":{},\"previewPath\":\"/prof