INSERT INTO `sys_oper_log` VALUES (867, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '15356061316', '启力学校(初中部)', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"15356061316\",\"createTime\":\"2026-03-12 09:31:48\",\"creatorId\":1912,\"grade\":3,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"数字资源的用途非常广泛：数字图书馆中的期刊资源为研究提供帮助，字库提供了各种字体让电子作文富有个性……各类资源库有不同的用途。丰富的文本、精美的图片、动听的音乐、精彩的视频等数字资源的使用，让学习和生活变得丰富多彩。\",\"questionId\":172,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":108}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-12 09:31:48', 15);
