INSERT INTO `sys_oper_log` VALUES (871, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '683484', '汉章小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"683484\",\"createTime\":\"2026-03-12 10:09:17\",\"creatorId\":1927,\"grade\":4,\"isPublic\":\"N\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"数字图像由许许多多的像素组成。图像尺寸一般用像素表示，通常像素越多，图像尺寸越大，清晰度也越高。在数字图像文件中，每个像素都由二进制数表示。同一图像采用不同编码规则生成不同类型的文件，如BMP、JPEG、PNG等，所需要的存储空间也不一样。\",\"questionId\":173,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":120}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-12 10:09:17', 15);
