INSERT INTO `sys_oper_log` VALUES (983, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '658632', '实验小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"6班\"],\"grade\":4,\"lessonId\":48,\"lessonNum\":1,\"lessonTitle\":\"练习\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"数字资源的用途非常广泛：数字图书馆中的期刊资源为研究提供帮助，字库提供了各种字体让电子作文富有个性……各类资源库有不同的用途。丰富的文本、精美的图片、动听的音乐、精彩的视频等数字资源的使用，让学习和生活变得丰富多彩。\",\"questionId\":172,\"questionScore\":35,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":108},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/11/课堂任务_20260311145344A484.pdf\",\"questionContent\":\"观看智能浇灌系统和智能通风系统展示视频，选择其一填表：\\n\",\"questionId\":171,\"questionScore\":30,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-11 14:54:27\",\"itemId\":29,\"itemName\":\"表格内容填写正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":171,\"updateTime\":\"2026-03-11 14:54:27\"}]},{\"answer\":\"C\",\"optionA\":\"图像信息化\",\"optionB\":\"图像科技化\",\"optionC\":\"图像数字化\",\"optionD\":\"图像采集\",\"orderNum\":3,\"params\":{},\"questionContent\":\"用相机、手机等数字设备将采集到的画面转化成计算机能处理的数字图像的过程就是（   ）\",\"questionId\":206,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"顺序结构\",\"optionB\":\"分支结构\",\"optionC\":\"循环结构\",\"optionD\":\"选择结构\",\"orderNum\":4,\"params\":{},\"questionContent\":\"猜数字游戏中，用于反复让用户输入的结构是\",\"questionId\":115,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"排序法 \",\"optionB\":\"枚举法\",\"optionC\":\"加密法\",\"optionD\":\"压缩\",\"orderNum\":5,\"params\":{},\"questionContent\":\"在“鸡兔同笼”问题中，常用的算法思想是\",\"questionId\":114,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"随意性\",\"optionB\":\"有限性\",\"optionC\":\"娱乐性\",\"optionD\":\"模糊性\",\"orderNum\":6,\"params\":{},\"questionContent\":\"下列哪一项属于算法的基本特征？\",\"questionId\":113,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"F\",\"orderNum\":7,\"params\":{},\"questionContent\":\"在数字图像文件中，每个像素都由十进制数表示。\",\"questionId\":208,\"questionScore\":5,\"questionType\":\"judgment\",\"scoringItems\":[]},{\"answer\":\"F\",\"orderNum\":8,\"params\":{},\"questionContent\":\"二分查找比顺序查找效率低\",\"questionId\":117,\"questionScore\":5,\"questionType\":\"judgment\",\"scoringItems\":[]}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"6班\"],\"grade\":4,\"lessonId\":48,\"lessonNum\":1,\"lessonTitle\":\"练习\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"数字资源的用途非常广泛：数字图书馆中的期刊资源为研究提供帮助，字库提供了各种字体让电子作文富有个性……各类资源库有不同的用途。丰富的文本、精美的图片、动听的音乐、精彩的视频等数字资源的使用，让学习和生活变得丰富多彩。\",\"questionId\":172,\"questionScore\":35,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":108},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/11/课堂任务_20260311145344A484.pdf\",\"questionContent\":\"观看智能浇灌系统和智能通风系统展示视频，选择其一填表：\\n\",\"questionId\":171,\"questionScore\":30,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-11 14:54:27\",\"itemId\":29,\"itemName\":\"表格内容填写正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":171,\"updateTime\":\"2026-03-11 14:54:27\"}]},{\"answer\":\"C\",\"optionA\":\"图像信息化\",\"optionB\":\"图像科技化\",\"optionC\":\"图像数字化\",\"optionD\":\"图像采集\",\"orderNum\":3,\"params\":{},\"questionContent\":\"用相机、手机等数字设备将采集到的画面转化成计算机能处理的数字图像的过程就是（   ）\",\"questionId\":206,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"顺序结构\",\"optionB\":\"分支结构\",\"optionC\":\"循环结构\",\"optionD\":\"选择结构\",\"orderNum\":4,\"params\":{},\"questionContent\":\"猜数字游戏中，用于反复让用户输入的结构是\",\"questionId\":115,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"排序法 \",\"optionB\":\"枚举法\",\"optionC\":\"加密法\",\"optionD\":\"压缩\",\"orderNum\":5,\"params\":{},\"questionContent\":\"在“鸡兔同笼”问题中，常用的算法思想是\",\"questionId\":114,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"随意性\",\"optionB\":\"有限性\",\"optionC\":\"娱乐性\",\"optionD\":\"模糊性\",\"orderNum\":6,\"params\":{},\"questionContent\":\"下列哪一项属于算法的基本特征？\",\"questionId\":113,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"F\",\"orderNum\":7,\"params\":{},\"questionContent\":\"在数字图像文件中，每个像素都由十进制数表示。\",\"questionId\":208,\"questionScore\":5,\"questionType\":\"judgment\",\"scoringItems\":[]},{\"answer\":\"F\",\"orderNum\":8,\"params\":{},\"questionContent\":\"二分查找比顺序查找效率低\",\"questionId\":117,\"questionScore\":5,\"questionTyp', 0, NULL, '2026-03-13 09:47:10', 22);
