INSERT INTO `sys_oper_log` VALUES (1031, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"7班\",\"4班\",\"2班\",\"8班\",\"10班\",\"5班\",\"6班\"],\"grade\":6,\"lessonId\":39,\"lessonNum\":1,\"lessonTitle\":\"4-反馈的实现\",\"params\":{},\"questions\":[{\"lessonId\":39,\"orderNum\":1,\"params\":{},\"questionContent\":\"反馈的实现是通过传感器对系统的输出量进行检测，并与输入量比较来判断是否达成预期的过程。传感器如同人体感官，负责获取环境信息。比较器接收传感器传回的实际输出量，与预设输入量对比计算出偏差值。\",\"questionId\":170,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":94}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"7班\",\"4班\",\"2班\",\"8班\",\"10班\",\"5班\",\"6班\"],\"grade\":6,\"lessonId\":39,\"lessonNum\":1,\"lessonTitle\":\"4-反馈的实现\",\"params\":{},\"questions\":[{\"lessonId\":39,\"orderNum\":1,\"params\":{},\"questionContent\":\"反馈的实现是通过传感器对系统的输出量进行检测，并与输入量比较来判断是否达成预期的过程。传感器如同人体感官，负责获取环境信息。比较器接收传感器传回的实际输出量，与预设输入量对比计算出偏差值。\",\"questionId\":170,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":94}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-13 12:29:06', 32);
INSERT INTO `sys_oper_log` VALUES (1032, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '15258105210', '新港小学', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"15258105210\",\"createTime\":\"2026-03-13 13:23:43\",\"creatorId\":1915,\"filePath\":\"/profile/upload/2026/03/13/3、观察系统-任务单_20260313132306A049.docx\",\"grade\":5,\"isPublic\":\"N\",\"lessonNum\":3,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/3、观察系统-任务单_20260313132306A049.pdf\",\"previewStatus\":\"pending\",\"questionContent\":\"完成操作题\",\"questionId\":210,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":36,\"itemName\":\"完成任务单\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":210}],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-13 13:23:43', 17);
INSERT INTO `sys_oper_log` VALUES (1033, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '15258105210', '新港小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"5班\",\"2班\"],\"grade\":5,\"lessonId\":49,\"lessonNum\":1,\"lessonTitle\":\"3、观察系统\",\"params\":{},\"questions\":[{\"lessonId\":49,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。\",\"questionId\":168,\"questionScore\":50,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":179},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/3、观察系统-任务单_20260313132306A049.pdf\",\"questionContent\":\"完成操作题\",\"questionId\":210,\"questionScore\":50,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-13 13:23:43\",\"itemId\":36,\"itemName\":\"完成任务单\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":210,\"updateTime\":\"2026-03-13 13:23:43\"}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"5班\",\"2班\"],\"grade\":5,\"lessonId\":49,\"lessonNum\":1,\"lessonTitle\":\"3、观察系统\",\"params\":{},\"questions\":[{\"lessonId\":49,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。\",\"questionId\":168,\"questionScore\":50,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":179},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/3、观察系统-任务单_20260313132306A049.pdf\",\"questionContent\":\"完成操作题\",\"questionId\":210,\"questionScore\":50,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-13 13:23:43\",\"itemId\":36,\"itemName\":\"完成任务单\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":210,\"updateTime\":\"2026-03-13 13:23:43\"}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-13 13:24:43', 22);
