INSERT INTO `sys_oper_log` VALUES (1036, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '15258105210', '新港小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"5班\",\"2班\"],\"grade\":5,\"lessonId\":49,\"lessonNum\":3,\"lessonTitle\":\"3、观察系统\",\"params\":{},\"questions\":[{\"lessonId\":49,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。\",\"questionId\":168,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":179},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/3、观察系统-任务单_20260313132306A049.pdf\",\"questionContent\":\"完成操作题\",\"questionId\":210,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-13 13:23:43\",\"itemId\":36,\"itemName\":\"完成任务单\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":210,\"updateTime\":\"2026-03-13 13:23:43\"}]},{\"answer\":\"B\",\"optionA\":\"进行思考和学习\",\"optionB\":\"消化食物，吸收营养\",\"optionC\":\"输送血液和氧气\",\"optionD\":\"感受外界环境变化\",\"orderNum\":3,\"params\":{},\"questionContent\":\"人体消化系统是一个生物系统，它的主要目标是\",\"questionId\":212,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"增加系统的组成部分，让它变得更复杂\",\"optionB\":\"更换系统中所有的部分\",\"optionC\":\"让系统更好地实现目标，运行更高效、更稳定\",\"optionD\":\"只保留系统中最重要的一个部分\",\"orderNum\":4,\"params\":{},\"questionContent\":\"当我们说“优化系统”时，通常是为了（ ）\",\"questionId\":211,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"5班\",\"2班\"],\"grade\":5,\"lessonId\":49,\"lessonNum\":3,\"lessonTitle\":\"3、观察系统\",\"params\":{},\"questions\":[{