INSERT INTO `sys_oper_log` VALUES (1038, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '15258105210', '新港小学', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\"],\"grade\":4,\"lessonId\":52,\"lessonNum\":1,\"lessonTitle\":\"3、字符编码\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"数字资源的用途非常广泛：数字图书馆中的期刊资源为研究提供帮助，字库提供了各种字体让电子作文富有个性……各类资源库有不同的用途。丰富的文本、精美的图片、动听的音乐、精彩的视频等数字资源的使用，让学习和生活变得丰富多彩。\",\"questionId\":172,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":108},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/字符编码-任务单_20260313133320A050.pdf\",\"questionContent\":\"完成任务单\",\"questionId\":213,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-13 13:33:33\",\"itemId\":37,\"itemName\":\"完成任务单\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":213,\"updateTime\":\"2026-03-13 13:33:33\"}]},{\"answer\":\"C\",\"optionA\":\"图像信息化\",\"optionB\":\"图像科技化\",\"optionC\":\"图像数字化\",\"optionD\":\"图像采集\",\"orderNum\":3,\"params\":{},\"questionContent\":\"用相机、手机等数字设备将采集到的画面转化成计算机能处理的数字图像的过程就是（   ）\",\"questionId\":206,\"questionScore\":20,\"questionType\":\"choice\",\"scoringItems\":[]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\"],\"grade\":4,\"lessonId\":52,\"lessonNum\":1,\"lessonTitle\":\"3、字符编码\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"数字资源的用途非常广泛：数字图书馆中的期刊资源为研究提供帮助，字库提供了各种字体让电子作文富有个性……各类资源库有不同的用途。丰富的文本、精美的图片、动听的音乐、精彩的视频等数字资源的使用，让学习和生活变得丰富多彩。\",\"questionId\":172,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":108},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/