INSERT INTO `sys_oper_log` VALUES (1072, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/question', '127.0.0.1', '内网IP', '{\"createBy\":\"657430\",\"createTime\":\"2026-03-13 14:40:57\",\"creatorId\":1906,\"grade\":8,\"isPublic\":\"N\",\"lessonNum\":5,\"params\":{},\"questionContent\":\"《第8课人工智能中的算法》数据、算法和算力是人工智能的三大技术基础，其中，算法是人工智能的核心和根基，算法的发展将直接推动人工智能的发展。搜索是人工智能解决问题的基本方法之一，搜索策略的优劣将直接影响智能系统的性能与效率。逻辑推理是人类思维活动的一个重要功能，通过演绎和归纳等手段对已有观测现象进行分析，并加以判断。人工智能技术在预测学领域发挥出越来越重要的作用，通过预测未来发展趋势，帮助人们做出科学合理的决策。\",\"questionId\":214,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":207}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-13 14:40:57', 10);
