INSERT INTO `sys_oper_log` VALUES (1089, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"11班\"],\"grade\":8,\"lessonId\":53,\"lessonNum\":5,\"lessonTitle\":\"八下5语音识别技术\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"《第8课人工智能中的算法》数据、算法和算力是人工智能的三大技术基础，其中，算法是人工智能的核心和根基，算法的发展将直接推动人工智能的发展。搜索是人工智能解决问题的基本方法之一，搜索策略的优劣将直接影响智能系统的性能与效率。逻辑推理是人类思维活动的一个重要功能，通过演绎和归纳等手段对已有观测现象进行分析，并加以判断。人工智能技术在预测学领域发挥出越来越重要的作用，通过预测未来发展趋势，帮助人们做出科学合理的决策。\",\"questionId\":214,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":207},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/8-5  作业_20260313144654A164.pdf\",\"questionContent\":\"完成八下第5课练习\",\"questionId\":220,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-13 14:47:21\",\"itemId\":40,\"itemName\":\"填空题正确\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":220,\"updateTime\":\"2026-03-13 14:47:21\"},{\"createTime\":\"2026-03-13 14:47:21\",\"itemId\":41,\"itemName\":\"操作题正确\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":220,\"updateTime\":\"2026-03-13 14:47:21\"}]},{\"answer\":\"C\",\"optionA\":\"语言处理\",\"optionB\":\"特征提取\",\"optionC\":\"声音数字化\",\"optionD\":\"模式匹配\",\"orderNum\":3,\"params\":{},\"questionContent\":\"《第5课》语音识别的过程中，第一步是什么？ \",\"questionId\":219,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"语音输入法\",\"optionB\":\"语音控制家电\",\"optionC\":\"人脸识别\",\"optionD\":\"语音助手\",\"orderNum\":4,\"params\":{},\"questionContent\":\"《第5课》语音识别技术的应用场景不包括以下哪一项？\",\"questionId\":218,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"噪音环境\",\"optionB\":\"发音清晰度\",\"optionC\":\"录音设备的质量\",\"optionD\":\"说话人的性别\",\"orderNum\":5,\"params\":