INSERT INTO `sys_oper_log` VALUES (1091, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/lesson/save-all', '127.0.0.1', '内网IP', '{\"assignedClassCodes\":[\"11班\"],\"grade\":8,\"lessonId\":46,\"lessonNum\":3,\"lessonTitle\":\"八下3人工智能技术基础\",\"params\":{},\"questions\":[{\"lessonId\":46,\"orderNum\":1,\"params\":{},\"questionContent\":\"数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能\",\"questionId\":122,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":219},{\"filePath\":\"/profile/upload/2026/03/12/第3.4课  作业_20260312153932A626.docx\",\"lessonId\":46,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/12/第3.4课  作业_20260312153932A626.pdf\",\"questionContent\":\"完成八下第3课作业\",\"questionId\":174,\"questionScore\":70,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":30,\"itemName\":\"填空题正确\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":174},{\"itemId\":31,\"itemName\":\"选择题正确\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":174}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"11班\"],\"grade\":8,\"lessonId\":46,\"lessonNum\":3,\"lessonTitle\":\"八下3人工智能技术基础\",\"params\":{},\"questions\":[{\"lessonId\":46,\"orderNum\":1,\"params\":{},\"questionContent\":\"数据、算法、算力构成人工智能的三大技术基础，三者相互影响、相互促进、缺一不可。数据是人工智能的基础，有了足够的数据，人工智能就能不断学习和提高。算法是人工智能的核心，实现了从数据中发现规律、预测结果和决策的过程，是让计算机具有类似人类智能的关键所在。算力即计算机的计算能力，代表着数据处理能力的强弱，是人工智能发展的动力。从中央处理器、图形处理器到人工智能专用芯片，算力的提升让大规模数据处理效率得到飞跃，推动人工智能为人类创造出更多可能\",\"questionId\":122,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":219},{\"filePath\":