INSERT INTO `sys_oper_log` VALUES (1105, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/question', '10.52.62.117', '内网IP', '{\"createBy\":\"657430\",\"createTime\":\"2026-03-16 09:09:03\",\"creatorId\":1906,\"grade\":7,\"isPublic\":\"N\",\"lessonNum\":5,\"params\":{},\"questionContent\":\"7-5物联网感知层通过感知和识别等技术，不断获取物理世界的信息，让物体“开口说话、发布信息”，从而实现信息采集和物体识别，实现物理世界与虚拟世界高度融合，为有效地感知物理世界，感知技术是物联网中信息获取的重要技术。感知技术包含传感器技术、定位技术等，其中，传感器技术在感知层的应用尤为普遍。传感器是一种能将感受的信息按一定规律转换成可输出电信号的器件或装置，它是物联网的“感觉器官”，用于感知、探测、采集物理世界的各种形态和信息。\",\"questionId\":221,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":215}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 09:09:03', 16);
INSERT INTO `sys_oper_log` VALUES (1106, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '675077', '塔山中学', '/business/question', '10.52.89.224', '内网IP', '{\"createBy\":\"675077\",\"createTime\":\"2026-03-16 09:16:09\",\"creatorId\":896,\"filePath\":\"/profile/upload/2026/03/16/实验单 - 常见的传感器_20260316091557A248.docx\",\"grade\":7,\"isPublic\":\"Y\",\"lessonNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/实验单 - 常见的传感器_20260316091557A248.pdf\",\"previewStatus\":\"pending\",\"questionContent\":\"常见的传感器\",\"questionId\":222,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":42,\"itemName\":\"分析正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":222}],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 09:16:09', 16);
INSERT INTO `sys_oper_log` VALUES (1107, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '675077', '塔山中学', '/business/question', '10.52.89.224', '内网IP', '{\"createBy\":\"675077\",\"createTime\":\"2026-03-16 09:17:41\",\"creatorId\":896,\"grade\":7,\"isPublic\":\"Y\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"传感器是能感受到被测量的信息，并能将感受到的信息，按一定规律变换成为电信号或其他所需形式的信息输出，以满足信息的传输、处理、存储、显示、记录和控制等要求的检测装置。 传感器的存在和发展，让物体有了触觉、味觉和嗅觉等感官，让物体变得活了起来，传感器是人类五官的延长。 传感器具有微型化、数字化、智能化、多功能化、系统化、网络化等特点，它是实现自动检测和自动控制的首要环节。\",\"questionId\":223,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":183}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 09:17:41', 13);
INSERT INTO `sys_oper_log` VALUES (1108, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '675077', '塔山中学', '/business/question', '10.52.89.224', '内网IP', '{\"createBy\":\"675077\",\"createTime\":\"2026-03-16 09:18:54\",\"creatorId\":896,\"grade\":8,\"isPublic\":\"Y\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"人工智能算法主要分为搜索算法、推理算法和预测算法。搜索算法是利用计算机的高性能来有目的的穷举一个问题的部分或所有的可能情况，从而求出问题的解的一种方法。面向知识图谱的推理主要围绕关系的推理展开，即基于图谱中已有的事实或关系推断出未知的事实或关系，一般着重考察实体、关系和图谱结构三个方面的特征信息。预测算法大多基于回归分析，相关分析研究的是现象之间是否相关、相关的方向和密切程度。\",\"questionId\":224,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":190}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 09:18:54', 9);
