INSERT INTO `sys_oper_log` VALUES (1119, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/lesson/save-all', '10.52.62.117', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\"],\"grade\":7,\"lessonId\":56,\"lessonNum\":5,\"lessonTitle\":\"七下5\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"7-5物联网感知层通过感知和识别等技术，不断获取物理世界的信息，让物体“开口说话、发布信息”，从而实现信息采集和物体识别，实现物理世界与虚拟世界高度融合，为有效地感知物理世界，感知技术是物联网中信息获取的重要技术。感知技术包含传感器技术、定位技术等，其中，传感器技术在感知层的应用尤为普遍。传感器是一种能将感受的信息按一定规律转换成可输出电信号的器件或装置，它是物联网的“感觉器官”，用于感知、探测、采集物理世界的各种形态和信息。\",\"questionId\":221,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":215},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/七下第5课 《感知与识别》 作业_20260316092738A250.pdf\",\"questionContent\":\"完成七下第五课作业\",\"questionId\":231,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-16 09:28:09\",\"itemId\":44,\"itemName\":\"活动一\",\"itemScore\":30,\"orderNum\":0,\"params\":{},\"questionId\":231,\"updateTime\":\"2026-03-16 09:28:09\"},{\"createTime\":\"2026-03-16 09:28:09\",\"itemId\":45,\"itemName\":\"活动二\",\"itemScore\":40,\"orderNum\":1,\"params\":{},\"questionId\":231,\"updateTime\":\"2026-03-16 09:28:09\"},{\"createTime\":\"2026-03-16 09:28:09\",\"itemId\":46,\"itemName\":\"活动三\",\"itemScore\":30,\"orderNum\":2,\"params\":{},\"questionId\":231,\"updateTime\":\"2026-03-16 09:28:09\"}]},{\"answer\":\"C\",\"optionA\":\"芯片\",\"optionB\":\"天线\",\"optionC\":\"条码\",\"optionD\":\"封装材料\",\"orderNum\":3,\"params\":{},\"questionContent\":\"以下不属于射频识别电子标签内部组成的是（）\",\"questionId\":230,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"存储数据\",\"optionB\":\"处理数据\",\"optionC\":\"采集数据\",\"optionD\":\"显示数据\",\"orderNum\":4,\"params\":{},\"questionContent\":\"在物联网中，传感器的主要作用是什么？\",\"questionId\":229,\"questionScore\":2,\"que