INSERT INTO `sys_oper_log` VALUES (1129, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/lesson/save-all', '10.52.27.200', '内网IP', '{\"assignedClassCodes\":[\"3班\",\"1班\",\"5班\",\"2班\",\"4班\",\"6班\",\"7班\"],\"grade\":8,\"lessonId\":38,\"lessonNum\":1,\"lessonTitle\":\"4-人工智能的影响\",\"params\":{},\"questions\":[{\"lessonId\":38,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。\",\"questionId\":168,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":179},{\"filePath\":\"/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.docx\",\"lessonId\":38,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.pdf\",\"questionContent\":\"课堂探究\",\"questionId\":169,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":28,\"itemName\":\"答案\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":169}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"3班\",\"1班\",\"5班\",\"2班\",\"4班\",\"6班\",\"7班\"],\"grade\":8,\"lessonId\":38,\"lessonNum\":1,\"lessonTitle\":\"4-人工智能的影响\",\"params\":{},\"questions\":[{\"lessonId\":38,\"orderNum\":1,\"params\":{},\"questionContent\":\"人工智能的发展经历了三起两落的漫长过程，如今的全面爆发主要得益于数据算法和算力这三大基础技术的飞跃。人工智能正深刻改变着我们的社会，它不仅赋能生活，通过智能管家和智慧城市让日常出行更加便捷，还赋能经济，在全自动化的智慧港口和精准测算的智慧农业等领域大幅提高了生产效率。与此同时，人工智能在推动社会进步的同时，也带来了传统就业岗位减少和数据隐私安全等现实挑战。\",\"questionId\":168,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":179},{\"filePath\":\"/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.docx\",\"lessonId\":38,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/10/课堂探究任务单（学生端）_20260310151507A352.pdf\",\"questionContent\":\"课堂探究\",\"questionId\":169,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":28,\"itemName\":\"答案\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":169}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-16 09:59:09', 24);
