INSERT INTO `sys_oper_log` VALUES (1136, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '698051', '贤庠学校(初中部)', '/business/question', '10.52.97.200', '内网IP', '{\"createBy\":\"698051\",\"createTime\":\"2026-03-16 10:28:01\",\"creatorId\":1893,\"filePath\":\"/profile/upload/2026/03/16/第5课  感知与识别_20260316102622A256.docx\",\"grade\":7,\"isPublic\":\"N\",\"lessonNum\":5,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/第5课  感知与识别_20260316102622A256.pdf\",\"previewStatus\":\"pending\",\"questionContent\":\"按要求完成任务单内容\",\"questionId\":296,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":57,\"itemName\":\"通过传感、定位等技术学习，了解物联网感知层信息采集和获取方式\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":296},{\"itemId\":58,\"itemName\":\"通过认识条码、二维码及RFID识别设备，了解物联网识别技术\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":296}],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 10:28:01', 24);
INSERT INTO `sys_oper_log` VALUES (1137, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/lesson/save-all', '10.52.27.200', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\"],\"grade\":7,\"lessonId\":57,\"lessonNum\":2,\"lessonTitle\":\"走进物联网\",\"params\":{},\"questions\":[{\"answer\":\"\",\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网是互联网充分发展的产物，是物理世界和数字世界之间的桥梁。物联网具有全面感知、可靠传递、智能处理等特征。物联网一般由感知层、网络层、平台层、应用层四层组成。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。平台层是在云平台基础上构建的基础计算设施，功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。应用层是物联网和用户的接口。\",\"questionId\":167,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":222},{\"answer\":\"D\",\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":2,\"params\":{},\"questionContent\":\"水分传感器是物联网架构中（     ）的设备？\",\"questionId\":161,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"全面感知\",\"optionB\":\"可靠传递\",\"optionC\":\"可靠决策\",\"optionD\":\"智能处理\",\"orderNum\":3,\"params\":{},\"questionContent\":\"利用云计算、数据挖掘以及模糊识别等智能技术，对接收到的海量数据与信息进行分析、处理，以进行智能化决策，体现了物联网的（         ）特征。\",\"questionId\":162,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":4,\"params\":{},\"questionContent\":\"物联网的（       ）功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。\",\"questionId\":163,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":5,\"params\":{},\"questionContent\":\"自动浇灌物联系统原型中，物联数据中台是属于（       ）\",\"questionId\":164,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"利用摄像头拍录汽车牌照图片属于物联网感知层；\",\"optionB\":\"将图片传送到平台层进行数据处理需要通过网络层。\",\"optionC\":\"平台层中运用人工智能图像识别技术识别图片中的车牌号码判断是否为本小区车辆，体现了物联网的全面感知特征。\",\"optionD\":\"拦车杆根据指令升起，是物联网应用层上的智能应用。\",\"orderNum\":6,\"params\":{},\"questionContent\":\"关于只允许本小区车辆进入的无人看守停车场，下列说法不正确的是（     ）\",\"questionId\":165,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]}],\"randomChoiceCount\":4,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMod', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\"],\"grade\":7,\"lessonId\":57,\"lessonNum\":2,\"lessonTitle\":\"走进物联网\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网是互联网充分发展的产物，是物理世界和数字世界之间的桥梁。物联网具有全面感知、可靠传递、智能处理等特征。物联网一般由感知层、网络层、平台层、应用层四层组成。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。平台层是在云平台基础上构建的基础计算设施，功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。应用层是物联网和用户的接口。\",\"questionId\":167,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":222},{\"answer\":\"D\",\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":2,\"params\":{},\"questionContent\":\"水分传感器是物联网架构中（     ）的设备？\",\"questionId\":161,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"全面感知\",\"optionB\":\"可靠传递\",\"optionC\":\"可靠决策\",\"optionD\":\"智能处理\",\"orderNum\":3,\"params\":{},\"questionContent\":\"利用云计算、数据挖掘以及模糊识别等智能技术，对接收到的海量数据与信息进行分析、处理，以进行智能化决策，体现了物联网的（         ）特征。\",\"questionId\":162,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":4,\"params\":{},\"questionContent\":\"物联网的（       ）功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。\",\"questionId\":163,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"option