INSERT INTO `sys_oper_log` VALUES (1180, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '466749', '高塘学校(初中部)', '/business/lesson/save-all', '10.52.238.241', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\"],\"grade\":6,\"lessonId\":59,\"lessonNum\":2,\"lessonTitle\":\"六下第2课\",\"params\":{},\"questions\":[{\"answer\":\"\",\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"控制系统一般分为开环控制和闭环控制两种形态。开环控制是指系统的输出量不会返回输入端与输入量进行比较，整个控制过程没有反馈环节。例如，楼宇外墙的霓虹灯一旦开启，就会按照设定程序运行，不会根据外界光线的变化自动调节。闭环控制则不同，它会将输出量通过检测装置返回到输入端，与输入量进行比较，形成闭合回路，从而实现对系统的精准控制。比如智能空调，它能根据室内实际温度与设定温度的差异自动调节运行状态。生活中还有很多这样的例子：自动喷泉、校园铃声属于开环控制；而路灯自动亮灭、农场自动灌溉则属于闭环控制。随着计算机技术的发展，闭环控制的应用越来越广泛，让我们的生活更加智能和便利。\",\"questionId\":312,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":15,\"wordCount\":285},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/操作文件_20260316125206A364.pdf\",\"questionContent\":\"按老师要求提交。\",\"questionId\":313,\"questionScore\":25,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-16 12:52:35\",\"itemId\":59,\"itemName\":\"正确\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":313,\"updateTime\":\"2026-03-16 12:52:35\"},{\"createTime\":\"2026-03-16 12:52:35\",\"itemId\":60,\"itemName\":\"完整\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":313,\"updateTime\":\"2026-03-16 12:52:35\"}]},{\"answer\":\"A\",\"optionA\":\"开环控制\",\"optionB\":\"闭环控制\",\"optionC\":\"反馈控制\",\"optionD\":\"自适应控制\",\"orderNum\":3,\"params\":{},\"questionContent\":\"楼宇外墙霓虹灯控制系统属于什么类型？\",\"questionId\":307,\"questionScore\":3,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"输入\",\"optionB\":\"输出\",\"optionC\":\"反馈\",\"optionD\":\"干扰\",\"orderNum\":4,\"params\":{},\"questionContent\":\"在闭环控制系统中，形成闭合回路的关键环节是？\",\"questionId\":308,\"questionScore\":3,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"输出量参与控制\",\"optionB\":\"系统能自动修正偏差\",\"optionC\":\"控制精度较高\",\"optionD\":\"输出量不返回到输入端\",\"orderNum\":5,\"params\":{},\"questionContent\":\"下列哪项描述符合开环控制的特点？\",\"questionId\":309,\"questionScore\":3,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"开环控制\",\"optionB\":\"闭环控制\",\"optionC\":\"智能控制\",\"optionD\":\"自适应控制\",\"orderNum\":6,\"params\":{},\"questionContent\":\"自动喷泉控制系统通常属于？\",\"questionId\":3', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\"],\"grade\":6,\"lessonId\":59,\"lessonNum\":2,\"lessonTitle\":\"六下第2课\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"控制系统一般分为开环控制和闭环控制两种形态。开环控制是指系统的输出量不会返回输入端与输入量进行比较，整个控制过程没有反馈环节。例如，楼宇外墙的霓虹灯一旦开启，就会按照设定程序运行，不会根据外界光线的变化自动调节。闭环控制则不同，它会将输出量通过检测装置返回到输入端，与输入量进行比较，形成闭合回路，从而实现对系统的精准控制。比如智能空调，它能根据室内实际温度与设定温度的差异自动调节运行状态。生活中还有很多这样的例子：自动喷泉、校园铃声属于开环控制；而路灯自动亮灭、农场自动灌溉则属于闭环控制。随着计算机技术的发展，闭环控制的应用越来越广泛，让我们的生活更加智能和便利。\",\"questionId\":312,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":15,\"wordCount\":285},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/操作文件_20260316125206A364.pdf\",\"questionContent\":\"按老师要求提交。\",\"questionId\":313,\"questionScore\":25,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-16 12:52:35\",\"itemId\":59,\"itemName\":\"正确\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":313,\"updateTime\":\"2026-03-16 12:52:35\"},{\"createTime\":\"2026-03-16 12:52:35\",\"itemId\":60,\"itemName\":\"完整\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":313,\"updateTime\":\"2026-03-16 12:52:35\"}]},{\"answer\":\"A\",\"optionA\":\"开环控制\",\"optionB\":\"闭环控制\",\"optionC\":\"反馈控制\",\"optionD\":\"自适应控制\",\"orderNum\":3,\"params\":{},\"questionContent\":\"楼宇外墙霓虹灯控制系统属于什么类型？\",\"questionId\":307,\"questionScore\":3,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"输入\",\"optionB\":\"输出\",\"optionC\":\"反馈\",\"optionD\":\"干扰\",\"orderNum\":4,\"params\":{},\"questionContent\":\"在闭环控制系统中，形成闭合回路的关键环节是？\",\"questionId\":308,\"questionScore\":3,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"输出量参与控制\",\"optionB\":\"系统能自动修正偏差\",\"optionC\":\"控制精度较高\",\"optionD\":\"输出量不返回到输入端\",\"orderNum\":5,\"params\":{},\"questionContent\":\"下列哪项描述符合开环控制的特点？\",\"questionId\":309,\"questionScore\":3,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"开环控制\",\"optionB\":\"闭环控制\",\"optionC\":\"智能控制\",\"optionD\":\"自适应控制\",\"orderNum\":6,\"params\":{},\"questionContent\":\"自动喷泉控制系统通常属于？\",\"questionId\":310,\"questionScore\":3,\"questionTy', 0, NULL, '2026-03-16 12:53:46', 21);
INSERT INTO `sys_oper_log` VALUES (1181, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/question', '10.52.63.243', '内网IP', '{\"createBy\":\"657430\",\"createTime\":\"2026-03-16 12:54:25\",\"creatorId\":1906,\"grade\":8,\"isPublic\":\"N\",\"lessonNum\":5,\"params\":{},\"questionContent\":\"《第5课语音识别技术》语音识别一般会经历以下基本过程：通过数模转化得到一个数字声音信号，再对该声音信号进行预处理和特征提取，将该特征在声学模型中进行模式识别得到音素序列，最后将该音素序列在语言模型中查找概率最高的文本，并输出识别结果。声音数字化是指将连续变化的声音物理信号，每隔一段时间，测得模拟信号的电压值，给出该电压值相应的量化值，并在计算机中用0和1表示，将模拟信号转换为数字信号。\",\"questionId\":314,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":194}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 12:54:25', 9);
