INSERT INTO `sys_oper_log` VALUES (1200, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/lesson/save-all', '10.52.63.243', '内网IP', '{\"assignedClassCodes\":[\"11班\",\"9班\",\"10班\",\"12班\"],\"grade\":8,\"lessonId\":53,\"lessonNum\":5,\"lessonTitle\":\"八下5语音识别技术\",\"params\":{},\"questions\":[{\"lessonId\":53,\"orderNum\":1,\"params\":{},\"questionContent\":\"《第5课语音识别技术》语音识别一般会经历以下基本过程：通过数模转化得到一个数字声音信号，再对该声音信号进行预处理和特征提取，将该特征在声学模型中进行模式识别得到音素序列，最后将该音素序列在语言模型中查找概率最高的文本，并输出识别结果。声音数字化是指将连续变化的声音物理信号，每隔一段时间，测得模拟信号的电压值，给出该电压值相应的量化值，并在计算机中用0和1表示，将模拟信号转换为数字信号。\",\"questionId\":314,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":194},{\"filePath\":\"/profile/upload/2026/03/13/8-5  作业_20260313144654A164.docx\",\"lessonId\":53,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/8-5  作业_20260313144654A164.pdf\",\"questionContent\":\"完成八下第5课练习\",\"questionId\":220,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":40,\"itemName\":\"填空题正确\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":220},{\"itemId\":41,\"itemName\":\"操作题正确\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":220}]},{\"answer\":\"C\",\"lessonId\":53,\"optionA\":\"语言处理\",\"optionB\":\"特征提取\",\"optionC\":\"声音数字化\",\"optionD\":\"模式匹配\",\"orderNum\":3,\"params\":{},\"questionContent\":\"《第5课》语音识别的过程中，第一步是什么？ \",\"questionId\":219,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"lessonId\":53,\"optionA\":\"语音输入法\",\"optionB\":\"语音控制家电\",\"optionC\":\"人脸识别\",\"optionD\":\"语音助手\",\"orderNum\":4,\"params\":{},\"questionContent\":\"《第5课》语音识别技术的应用场景不包括以下哪一项？\",\"questionId\":218,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"lessonId\":53,\"optionA\":\"噪音环境\",\"optionB\":\"发音清晰度\",\"optionC\":\"录音设备的质量\",\"optionD\":\"说话人的性别\",\"orderNum\":5,\"params\":{},\"questionContent\":\"《第5课》下列哪个因素不会影响语音识别的准确性？\",\"questionId\":217,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":53,\"optionA\":\"将声音信号转换为音素\",\"optionB\":\"找出音素出现概率最高的词语\",\"optionC\":\"提供语音合成的功能\",\"optionD\":\"识别图像中的文字\",\"orderNum\":6,\"params\":{},\"questionContent\":\"《第5课》语言模型的主要作用是什么？\",\"questionId\":216,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"11班\",\"9班\",\"10班\",\"12班\"],\"grade\":8,\"lessonId\":53,\"lessonNum\":5,\"lessonTitle\":\"八下5语音识别技术\",\"params\":{},\"questions\":[{\"lessonId\":53,\"orderNum\":1,\"params\":{},\"questionContent\":\"《第5课语音识别技术》语音识别一般会经历以下基本过程：通过数模转化得到一个数字声音信号，再对该声音信号进行预处理和特征提取，将该特征在声学模型中进行模式识别得到音素序列，最后将该音素序列在语言模型中查找概率最高的文本，并输出识别结果。声音数字化是指将连续变化的声音物理信号，每隔一段时间，测得模拟信号的电压值，给出该电压值相应的量化值，并在计算机中用0和1表示，将模拟信号转换为数字信号。\",\"questionId\":314,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":194},{\"filePath\":\"/profile/upload/2026/03/13/8-5  作业_20260313144654A164.docx\",\"lessonId\":53,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/13/8-5  作业_20260313144654A164.pdf\",\"questionContent\":\"完成八下第5课练习\",\"questionId\":220,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":40,\"itemName\":\"填空题正确\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":220},{\"itemId\":41,\"itemName\":\"操作题正确\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":220}]},{\"answer\":\"C\",\"lessonId\":53,\"optionA\":\"语言处理\",\"optionB\":\"特征提取\",\"optionC\":\"声音数字化\",\"optionD\":\"模式匹配\",\"orderNum\":3,\"params\":{},\"questionContent\":\"《第5课》语音识别的过程中，第一步是什么？ \",\"questionId\":219,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"lessonId\":53,\"optionA\":\"语音输入法\",\"optionB\":\"语音控制家电\",\"optionC\":\"人脸识别\",\"optionD\":\"语音助手\",\"orderNum\":4,\"params\":{},\"questionContent\":\"《第5课》语音识别技术的应用场景不包括以下哪一项？\",\"questionId\":218,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"lessonId\":53,\"optionA\":\"噪音环境\",\"optionB\":\"发音清晰度\",\"optionC\":\"录音设备的质量\",\"optionD\":\"说话人的性别\",\"orderNum\":5,\"params\":{},\"questionContent\":\"《第5课》下列哪个因素不会影响语音识别的准确性？\",\"questionId\":217,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":53,\"optionA\":\"将声音信号转换为音素\",\"optionB\":\"找出音素出现概率最高的词语\",\"optionC\":\"提供语音合成的功能\",\"optionD\":\"识别图像中的文字\",\"orderNum\":6,\"params\":{},\"questionContent\":\"《第5课》语言模型的主要作用是什么？\",\"questionId\":216,\"questionScore\":2,\"questionType\":\"choice\",\"s', 0, NULL, '2026-03-16 13:02:51', 20);
INSERT INTO `sys_oper_log` VALUES (1201, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '698051', '贤庠学校(初中部)', '/business/lesson/save-all', '10.52.97.200', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\"],\"grade\":7,\"lessonId\":60,\"lessonNum\":1,\"lessonTitle\":\"感知与识别\",\"params\":{},\"questions\":[{\"answer\":\"\",\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"感知层是物联网信息采集的核心，通过传感、识别、定位技术实现物理与数字世界的融合。传感技术以传感器为核心，是物联网的 “感觉器官”，能将物理量转换为电信号。识别技术包含条码、二维码、RFID 技术，条形码和二维码通过光电设备识别信息，RFID 是无接触式自动识别技术，分无源、有源、半有源三类，在 ETC、产品溯源等领域广泛应用。学习中要掌握各类感知识别技术的原理，举例说明其生活应用，理解感知层多样化的信息采集方式。\",\"questionId\":179,\"questionScore\":10,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":204},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/第5课  感知与识别_20260316102622A256.pdf\",\"questionContent\":\"按要求完成任务单内容\",\"questionId\":296,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-16 10:28:01\",\"itemId\":57,\"itemName\":\"通过传感、定位等技术学习，了解物联网感知层信息采集和获取方式\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":296,\"updateTime\":\"2026-03-16 10:28:01\"},{\"createTime\":\"2026-03-16 10:28:01\",\"itemId\":58,\"itemName\":\"通过认识条码、二维码及RFID识别设备，了解物联网识别技术\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":296,\"updateTime\":\"2026-03-16 10:28:01\"}]},{\"answer\":\"D\",\"optionA\":\"A. 传感技术\",\"optionB\":\"B. 识别技术\",\"optionC\":\"C. 定位技术\",\"optionD\":\"D. 打印技术\",\"orderNum\":3,\"params\":{},\"questionContent\":\"1.物联网感知层的核心技术不包括（  ）\",\"questionId\":406,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"A. 麦克风\",\"optionB\":\"B. 条形码扫描器\",\"optionC\":\"C. 温度计\",\"optionD\":\"D. 摄像头\",\"orderNum\":4,\"params\":{},\"questionContent\":\"2.条形码识别技术的核心是通过什么设备获取信息？（  ）\",\"questionId\":407,\"questionScore\":10,\"questionT