INSERT INTO `sys_oper_log` VALUES (1208, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/question', '10.52.63.243', '内网IP', '{\"createBy\":\"657430\",\"createTime\":\"2026-03-16 13:35:36\",\"creatorId\":1906,\"grade\":8,\"isPublic\":\"N\",\"lessonNum\":6,\"params\":{},\"questionContent\":\"《第6课语音合成技术》语音合成的基本过程为：先将文本分解成音素，经过韵律处理后，再根据音素在语音库中找到发音单元，并输出拼接的发音单元，从而形成语音。计算机对中文进行文本分词有各种方法，如基于规则的规则分词法，基于统计的统计分词法。在音素分析的基础上，进一步参照人类语言中的韵律规则进行调整，规划出音段特征，如音高、音长和音强等，使合成语音能正确地表达语意，听起来更加自然。调用语音库中的音素单元，进行拼接和平滑处理，从而形成语音。\",\"questionId\":413,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":216}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 13:35:36', 10);
