INSERT INTO `sys_oper_log` VALUES (1217, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/lesson/save-all', '10.52.63.243', '内网IP', '{\"assignedClassCodes\":[\"13班\",\"14班\"],\"grade\":8,\"lessonId\":61,\"lessonNum\":6,\"lessonTitle\":\"八下第6课 语音合成技术\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"《第6课语音合成技术》语音合成的基本过程为：先将文本分解成音素，经过韵律处理后，再根据音素在语音库中找到发音单元，并输出拼接的发音单元，从而形成语音。计算机对中文进行文本分词有各种方法，如基于规则的规则分词法，基于统计的统计分词法。在音素分析的基础上，进一步参照人类语言中的韵律规则进行调整，规划出音段特征，如音高、音长和音强等，使合成语音能正确地表达语意，听起来更加自然。调用语音库中的音素单元，进行拼接和平滑处理，从而形成语音。\",\"questionId\":413,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":216},{\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/第六课 语音合成技术练习_20260316134816A465.pdf\",\"questionContent\":\"完成八下第6课作业\",\"questionId\":419,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"createTime\":\"2026-03-16 13:48:39\",\"itemId\":61,\"itemName\":\"填空题\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":419,\"updateTime\":\"2026-03-16 13:48:39\"},{\"createTime\":\"2026-03-16 13:48:39\",\"itemId\":62,\"itemName\":\"操作题\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":419,\"updateTime\":\"2026-03-16 13:48:39\"}]},{\"answer\":\"D\",\"optionA\":\"车载导航系统\",\"optionB\":\"医院叫号系统\",\"optionC\":\"电话查询系统\",\"optionD\":\" 图像识别系统\",\"orderNum\":3,\"params\":{},\"questionContent\":\"《第6课》语音合成技术的主要应用场景不包括以下哪项？\",\"questionId\":414,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"语言处理\",\"optionB\":\"韵律处理\",\"optionC\":\"单元拼接\",\"optionD\":\"语音输出\",\"orderNum\":4,\"params\":{},\"questionContent\":\"《第6课》语音合成的基本过程中，首先需要进行的是哪一步\",\"questionId\":415,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"optionA\":\"音素\",\"optionB\":\"语法和词法\",\"optionC\":\"音高、音长和音强\",\"optionD\":\" 