INSERT INTO `sys_oper_log` VALUES (1254, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/question', '10.52.27.117', '内网IP', '{\"createBy\":\"960250\",\"createTime\":\"2026-03-16 14:17:17\",\"creatorId\":1587,\"grade\":3,\"isPublic\":\"N\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"一身乌黑的羽毛，一对轻快有力的翅膀，加上剪刀似的尾巴，凑成了那样可爱的活泼的小燕子。\\n二三月的春日里，轻风微微地吹拂着，如毛的细雨由天上洒落着，千条万条的柔柳，红的白的黄的花，青的草，绿的叶，都像赶集似的聚拢来，形成了烂漫无比的春天。这时候，那些小燕子，那么伶俐可爱的小燕子，也由南方飞来，加入这光彩夺目的图画中，为春光平添了许多生趣。\\n小燕子带了它的剪刀似的尾巴，在阳光满地时，斜飞于旷亮无比的天空，叽的一声，已由这里的稻田上，飞到那边的高柳下了。\\n另有几只却在波光粼粼的湖面上横掠着，小燕子的翼尖或剪尾，偶尔沾了一下水面，那小圆晕便一圈一圈地荡漾开去。\",\"questionId\":421,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":14,\"wordCount\":275}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 14:17:17', 10);
