INSERT INTO `sys_oper_log` VALUES (1256, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/question', '10.52.27.117', '内网IP', '{\"createBy\":\"960250\",\"createTime\":\"2026-03-16 14:19:01\",\"creatorId\":1587,\"grade\":3,\"isPublic\":\"N\",\"lessonNum\":2,\"params\":{},\"questionContent\":\"荷叶挨挨挤挤的，像一个个碧绿的大圆盘。白荷花在这些大圆盘之间冒出来。有的才展开两三片花瓣儿。有的花瓣儿全展开了，露出嫩黄色的小莲蓬。有的还是花骨朵儿，看起来饱胀得马上要破裂似的。\\n我忽然觉得自己仿佛就是一朵荷花，穿着雪白的衣裳，站在阳光里。一阵微风吹过来，我就翩翩起舞，雪白的衣裳随风飘动。不光是我一朵，一池的荷花都在舞蹈。风过了，我停止了舞蹈，静静地站在那儿。蜻蜓飞过来，告诉我清早飞行的快乐。小鱼在脚下游过，告诉我昨夜做的好梦……\\n过了好一会儿，我才记起我不是荷花，我是在看荷花呢。\",\"questionId\":422,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":13,\"wordCount\":241}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-16 14:19:01', 9);
