INSERT INTO `sys_oper_log` VALUES (1315, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '698051', '贤庠学校(初中部)', '/business/lesson/save-all', '10.52.97.200', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\"],\"grade\":7,\"lessonId\":60,\"lessonNum\":5,\"lessonTitle\":\"感知与识别\",\"params\":{},\"questions\":[{\"answer\":\"\",\"lessonId\":60,\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"感知层是物联网信息采集的核心，通过传感、识别、定位技术实现物理与数字世界的融合。传感技术以传感器为核心，是物联网的 “感觉器官”，能将物理量转换为电信号。识别技术包含条码、二维码、RFID 技术，条形码和二维码通过光电设备识别信息，RFID 是无接触式自动识别技术，分无源、有源、半有源三类，在 ETC、产品溯源等领域广泛应用。学习中要掌握各类感知识别技术的原理，举例说明其生活应用，理解感知层多样化的信息采集方式。\",\"questionId\":179,\"questionScore\":10,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":204},{\"filePath\":\"/profile/upload/2026/03/16/第5课  感知与识别_20260316102622A256.docx\",\"lessonId\":60,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/第5课  感知与识别_20260316102622A256.pdf\",\"questionContent\":\"按要求完成任务单内容\",\"questionId\":296,\"questionScore\":40,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":57,\"itemName\":\"通过传感、定位等技术学习，了解物联网感知层信息采集和获取方式\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":296},{\"itemId\":58,\"itemName\":\"通过认识条码、二维码及RFID识别设备，了解物联网识别技术\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":296}]},{\"answer\":\"D\",\"lessonId\":60,\"optionA\":\"A. 传感技术\",\"optionB\":\"B. 识别技术\",\"optionC\":\"C. 定位技术\",\"optionD\":\"D. 打印技术\",\"orderNum\":3,\"params\":{},\"questionContent\":\"1.物联网感知层的核心技术不包括（  ）\",\"questionId\":406,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":60,\"optionA\":\"A. 麦克风\",\"optionB\":\"B. 条形码扫描器\",\"optionC\":\"C. 温度计\",\"optionD\":\"D. 摄像头\",\"orderNum\":4,\"params\":{},\"questionContent\":\"2.条形码识别技术的核心是通过什么设备获取信息？（  ）\",\"questionId\":407,\"questionScore\":10,\"questionType\":\"choic