INSERT INTO `sys_oper_log` VALUES (1318, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '657430', '弘正书院(初中部)', '/business/lesson/save-all', '10.52.62.117', '内网IP', '{\"assignedClassCodes\":[\"13班\",\"14班\",\"9班\",\"12班\",\"10班\"],\"grade\":8,\"lessonId\":61,\"lessonNum\":6,\"lessonTitle\":\"八下第6课 语音合成技术\",\"params\":{},\"questions\":[{\"lessonId\":61,\"orderNum\":1,\"params\":{},\"questionContent\":\"《第6课语音合成技术》语音合成的基本过程为：先将文本分解成音素，经过韵律处理后，再根据音素在语音库中找到发音单元，并输出拼接的发音单元，从而形成语音。计算机对中文进行文本分词有各种方法，如基于规则的规则分词法，基于统计的统计分词法。在音素分析的基础上，进一步参照人类语言中的韵律规则进行调整，规划出音段特征，如音高、音长和音强等，使合成语音能正确地表达语意，听起来更加自然。调用语音库中的音素单元，进行拼接和平滑处理，从而形成语音。\",\"questionId\":413,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":216},{\"filePath\":\"/profile/upload/2026/03/16/第六课 语音合成技术练习_20260316134816A465.docx\",\"lessonId\":61,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/第六课 语音合成技术练习_20260316134816A465.pdf\",\"questionContent\":\"完成八下第6课作业\",\"questionId\":419,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":61,\"itemName\":\"填空题\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":419},{\"itemId\":62,\"itemName\":\"操作题\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":419}]},{\"answer\":\"D\",\"lessonId\":61,\"optionA\":\"车载导航系统\",\"optionB\":\"医院叫号系统\",\"optionC\":\"电话查询系统\",\"optionD\":\" 图像识别系统\",\"orderNum\":3,\"params\":{},\"questionContent\":\"《第6课》语音合成技术的主要应用场景不包括以下哪项？\",\"questionId\":414,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"lessonId\":61,\"optionA\":\"语言处理\",\"optionB\":\"韵律处理\",\"optionC\":\"单元拼接\",\"optionD\":\"语音输出\",\"orderNum\":4,\"params\":{},\"questionContent\":\"《第6课》语音合成的基本过程中，首先需要进行的是哪一步\",\"questionId\":415,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"lessonId\":61,\"optionA\":\"音素\",\"optionB\":\"语法和词法\",\"optionC\":\"音高、音长和音强\",\"optionD\":\" 语音库中的发音单元\",\"orderNum\":5,\"params\":{},\"questionContent\":\"《第6课》在语音合成的过程中，韵律处理主要调整什么特征？ \",\"questionId\":416,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":61,\"optionA\":\"半小时左右、500 句\",\"optionB\":\"10 小时或 10000 句\",\"optionC\":\"1 小时或 1000 句\",\"optionD\":\"5 小时或 5000 句\",\"orderNum\":6,\"params\":{},\"questionContent\":\"《第6课》创建高质量的语音合成模型，传统方法需要多少真人原声录音？ \",\"questionId\"', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"13班\",\"14班\",\"9班\",\"12班\",\"10班\"],\"grade\":8,\"lessonId\":61,\"lessonNum\":6,\"lessonTitle\":\"八下第6课 语音合成技术\",\"params\":{},\"questions\":[{\"lessonId\":61,\"orderNum\":1,\"params\":{},\"questionContent\":\"《第6课语音合成技术》语音合成的基本过程为：先将文本分解成音素，经过韵律处理后，再根据音素在语音库中找到发音单元，并输出拼接的发音单元，从而形成语音。计算机对中文进行文本分词有各种方法，如基于规则的规则分词法，基于统计的统计分词法。在音素分析的基础上，进一步参照人类语言中的韵律规则进行调整，规划出音段特征，如音高、音长和音强等，使合成语音能正确地表达语意，听起来更加自然。调用语音库中的音素单元，进行拼接和平滑处理，从而形成语音。\",\"questionId\":413,\"questionScore\":30,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":216},{\"filePath\":\"/profile/upload/2026/03/16/第六课 语音合成技术练习_20260316134816A465.docx\",\"lessonId\":61,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/第六课 语音合成技术练习_20260316134816A465.pdf\",\"questionContent\":\"完成八下第6课作业\",\"questionId\":419,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":61,\"itemName\":\"填空题\",\"itemScore\":50,\"orderNum\":0,\"params\":{},\"questionId\":419},{\"itemId\":62,\"itemName\":\"操作题\",\"itemScore\":50,\"orderNum\":1,\"params\":{},\"questionId\":419}]},{\"answer\":\"D\",\"lessonId\":61,\"optionA\":\"车载导航系统\",\"optionB\":\"医院叫号系统\",\"optionC\":\"电话查询系统\",\"optionD\":\" 图像识别系统\",\"orderNum\":3,\"params\":{},\"questionContent\":\"《第6课》语音合成技术的主要应用场景不包括以下哪项？\",\"questionId\":414,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"lessonId\":61,\"optionA\":\"语言处理\",\"optionB\":\"韵律处理\",\"optionC\":\"单元拼接\",\"optionD\":\"语音输出\",\"orderNum\":4,\"params\":{},\"questionContent\":\"《第6课》语音合成的基本过程中，首先需要进行的是哪一步\",\"questionId\":415,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"C\",\"lessonId\":61,\"optionA\":\"音素\",\"optionB\":\"语法和词法\",\"optionC\":\"音高、音长和音强\",\"optionD\":\" 语音库中的发音单元\",\"orderNum\":5,\"params\":{},\"questionContent\":\"《第6课》在语音合成的过程中，韵律处理主要调整什么特征？ \",\"questionId\":416,\"questionScore\":2,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":61,\"optionA\":\"半小时左右、500 句\",\"optionB\":\"10 小时或 10000 句\",\"optionC\":\"1 小时或 1000 句\",\"optionD\":\"5 小时或 5000 句\",\"orderNum\":6,\"params\":{},\"questionContent\":\"《第6课》创建高质量的语音合成模', 0, NULL, '2026-03-17 10:24:56', 21);
