INSERT INTO `sys_oper_log` VALUES (1361, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '675077', '塔山中学', '/business/lesson/save-all', '10.52.30.246', '内网IP', '{\"assignedClassCodes\":[\"4班\",\"8班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":2,\"lessonTitle\":\"走进物联网\",\"params\":{},\"questions\":[{\"lessonId\":36,\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":2}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"4班\",\"8班\"],\"grade\":7,\"lessonId\":36,\"lessonNum\":2,\"lessonTitle\":\"走进物联网\",\"params\":{},\"questions\":[{\"lessonId\":36,\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网就像给世界装上了 “五官”，能让物体互相交流、自动工作，而感知与识别技术就是它的核心。感知技术依靠传感器，能收集温度、湿度、光线、声音等信息，就像我们用眼睛看、耳朵听。识别技术可以分辨物体、人脸、指纹和二维码，让设备 “认出” 目标。在生活里，这些技术随处可见：智能手环感知心跳，超市扫码器识别商品，门禁刷脸开门，智能家居根据环境自动调节。它们让生活更方便、更安全。\",\"questionId\":128,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":2}}', 0, NULL, '2026-03-17 13:56:40', 16);
