INSERT INTO `sys_oper_log` VALUES (1364, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '675077', '塔山中学', '/business/lesson/save-all', '10.52.90.243', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"10班\",\"2班\",\"3班\",\"5班\",\"6班\",\"7班\",\"9班\",\"4班\"],\"grade\":7,\"lessonId\":54,\"lessonNum\":1,\"lessonTitle\":\"常见的传感器\",\"params\":{},\"questions\":[{\"lessonId\":54,\"orderNum\":1,\"params\":{},\"questionContent\":\"传感器是能感受到被测量的信息，并能将感受到的信息，按一定规律变换成为电信号或其他所需形式的信息输出，以满足信息的传输、处理、存储、显示、记录和控制等要求的检测装置。 传感器的存在和发展，让物体有了触觉、味觉和嗅觉等感官，让物体变得活了起来，传感器是人类五官的延长。 传感器具有微型化、数字化、智能化、多功能化、系统化、网络化等特点，它是实现自动检测和自动控制的首要环节。\",\"questionId\":223,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183},{\"filePath\":\"/profile/upload/2026/03/16/实验单 - 常见的传感器_20260316091557A248.docx\",\"lessonId\":54,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/实验单 - 常见的传感器_20260316091557A248.pdf\",\"questionContent\":\"常见的传感器\",\"questionId\":222,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":42,\"itemName\":\"分析正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":222}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"10班\",\"2班\",\"3班\",\"5班\",\"6班\",\"7班\",\"9班\",\"4班\"],\"grade\":7,\"lessonId\":54,\"lessonNum\":1,\"lessonTitle\":\"常见的传感器\",\"params\":{},\"questions\":[{\"lessonId\":54,\"orderNum\":1,\"params\":{},\"questionContent\":\"传感器是能感受到被测量的信息，并能将感受到的信息，按一定规律变换成为电信号或其他所需形式的信息输出，以满足信息的传输、处理、存储、显示、记录和控制等要求的检测装置。 传感器的存在和发展，让物体有了触觉、味觉和嗅觉等感官，让物体变得活了起来，传感器是人类五官的延长。 传感器具有微型化、数字化、智能化、多功能化、系统化、网络化等特点，它是实现自动检测和自动控制的首要环节。\",\"questionId\":223,\"questionScore\":40,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":183},{\"filePath\":\"/profile/upload/2026/03/16/实验单 - 常见的传感器_20260316091557A248.docx\",\"lessonId\":54,\"orderNum\":2,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/16/实验单 - 常见的传感器_20260316091557A248.pdf\",\"questionContent\":\"常见的传感器\",\"questionId\":222,\"questionScore\":60,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":42,\"itemName\":\"分析正确\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":222}]}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-17 13:57:19', 25);
