INSERT INTO `sys_oper_log` VALUES (1367, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '667015', '东陈中学', '/business/question', '10.52.190.249', '内网IP', '{\"createBy\":\"667015\",\"createTime\":\"2026-03-17 14:01:27\",\"creatorId\":1916,\"grade\":7,\"isPublic\":\"N\",\"lessonNum\":6,\"params\":{},\"questionContent\":\"传感器是感知层的核心部件，种类繁多，功能各异。按照传感器的功能分类，常见的传感器可以与人类的五大感觉器官进行类比：光敏传感器对应眼睛，声音传感器对应耳朵，热敏传感器对应皮肤，气敏传感器对应鼻子，味敏传感器对应舌头。如图像传感器属于光敏传感器，是一种可将光学图像转换成电信号的设备，通常应用于数据相机和其他电子光学设备；声音传感器能采集环境中的声音，可应用于麦克风等拾音设备。\",\"questionId\":436,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":187}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-17 14:01:27', 8);
