INSERT INTO `sys_oper_log` VALUES (1387, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/question', '10.52.27.117', '内网IP', '{\"createBy\":\"960250\",\"createTime\":\"2026-03-17 15:57:07\",\"creatorId\":1587,\"grade\":7,\"isPublic\":\"N\",\"lessonNum\":3,\"params\":{},\"questionContent\":\"智能家居系统是指通过物联网技术将家中的各种设备连接到网络，可以实现家电控制、照明控制、防盗报警、环境监测；智慧交通是指将物联网技术有效运用于交通管理的智能化交通运输服务系统，通过对车辆、驾驶者、道路三个方面的数据进行处理，提供实时、全面、准确的交通信息，从而高效地利用交通资源。智慧物流以信息技术为支撑，在运输、仓储、包装、装卸搬运、流通加工、配送、信息服务等各个环节实现系统感知、全面分析。\",\"questionId\":438,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":5,\"wordCount\":196}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-17 15:57:07', 11);
