INSERT INTO `sys_oper_log` VALUES (1397, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/question', '10.52.27.117', '内网IP', '{\"answer\":\"B\",\"createBy\":\"960250\",\"createTime\":\"2026-03-17 16:10:03\",\"creatorId\":1587,\"grade\":7,\"isPublic\":\"Y\",\"lessonNum\":3,\"optionA\":\"小明使用手机闹钟每天定时起床，与以往相比生活更加规律。\",\"optionB\":\"小红家中的智能温控系统根据室内外温差自动调节室内温度，使居住环境更加舒适节能。\",\"optionC\":\"李老师在课堂上使用PPT讲解知识，与以往板书教学相比提高了教学效率。\",\"optionD\":\"小刚通过手机APP查看天气预报，提前准备出行衣物。\",\"params\":{},\"questionContent\":\"以下哪个场景应用了物联网技术？\",\"questionId\":448,\"questionType\":\"choice\",\"scoringItems\":[],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-17 16:10:03', 10);
INSERT INTO `sys_oper_log` VALUES (1398, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/question', '10.52.27.117', '内网IP', '{\"answer\":\"A\",\"createBy\":\"960250\",\"createTime\":\"2026-03-17 16:15:25\",\"creatorId\":1587,\"grade\":7,\"isPublic\":\"N\",\"lessonNum\":3,\"optionA\":\"交通领域，通过智能交通系统，可以实时收集和分析交通流量，实现信号灯的智能调控。\",\"optionB\":\"文学创作领域，辅助作者进行散文、诗歌的写作。\",\"optionC\":\"手工制作领域，指导人们进行陶艺、编织等手工创作。\",\"optionD\":\"书法绘画领域，帮助人们练习毛笔字和国画。\",\"params\":{},\"questionContent\":\"假设你参与了一个关于“智慧城市”的项目，你认为物联网技术有可能在以下哪个领域发挥重要作用？\",\"questionId\":449,\"questionType\":\"choice\",\"scoringItems\":[],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-17 16:15:25', 8);
INSERT INTO `sys_oper_log` VALUES (1399, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/lesson/save-all', '10.52.27.117', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\"],\"grade\":7,\"lessonId\":75,\"lessonNum\":3,\"lessonTitle\":\"物联网与生活\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"智能家居系统是指通过物联网技术将家中的各种设备连接到网络，可以实现家电控制、照明控制、防盗报警、环境监测；智慧交通是指将物联网技术有效运用于交通管理的智能化交通运输服务系统，通过对车辆、驾驶者、道路三个方面的数据进行处理，提供实时、全面、准确的交通信息，从而高效地利用交通资源。智慧物流以信息技术为支撑，在运输、仓储、包装、装卸搬运、流通加工、配送、信息服务等各个环节实现系统感知、全面分析。\",\"questionId\":438,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":196},{\"answer\":\"A\",\"optionA\":\"感知层\",\"optionB\":\"网络层\",\"optionC\":\"平台层\",\"optionD\":\"应用层\",\"orderNum\":2,\"params\":{},\"questionContent\":\"智能温度传感器、RFID 读卡器，在物联网四层架构中属于？（  ）\\n\",\"questionId\":440,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"感知层\",\"optionB\":\"网络层\",\"optionC\":\"应用层\",\"optionD\":\"平台层\",\"orderNum\":3,\"params\":{},\"questionContent\":\"负责数据传输与网络互联的 WiFi 路由器、蓝牙模块，归属架构中的（  ）\\n\\n\",\"questionId\":441,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"感知层\",\"optionB\":\"网络层\",\"optionC\":\"平台层\",\"optionD\":\"应用层\",\"orderNum\":4,\"params\":{},\"questionContent\":\"手机端智能家居控制 APP，属于物联网架构的（  ）\",\"questionId\":442,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"交通领域，通过智能交通系统，可以实时收集和分析交通流量，实现信号灯的智能调控。\",\"optionB\":\"文学创作领域，辅助作者进行散文、诗歌的写作。\",\"optionC\":\"手工制作领域，指导人们进行陶艺、编织等手工创作。\",\"optionD\":\"书法绘画领域，帮助人们练习毛笔字和国画。\",\"orderNum\":5,\"params\":{},\"questionContent\":\"假设你参与了一个关于“智慧城市”的项目，你认为物联网技术有可能在以下哪个领域发挥重要作用？\",\"questionId\":449,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"小明使用手机闹钟每天定时起床，与以往相比生活更加规律。\",\"optionB\":\"小红家中的智能温控系统根据室内外温差自动调节室内温度，使居住环境更加舒适节能。\",\"optionC\":\"李老师在课堂上使用PPT讲解知识，与以往板书教学相比提高了教学效率。\",\"optionD\":\"小刚通过手机APP查看天气预报，提前准备出行衣物。\",\"orderNum\":6,\"params\":{},\"questionContent\":\"以下哪个场景应用了物联网技术？\",\"questionId\":448,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"全面感知\",\"optionB\":\"可靠传递\",\"optionC\":\"智能处理\",\"optionD\":\"离线操控\",\"orderNum\":7,\"params\":{},\"questio', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\",\"5班\",\"6班\",\"7班\",\"8班\"],\"grade\":7,\"lessonId\":75,\"lessonNum\":3,\"lessonTitle\":\"物联网与生活\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"智能家居系统是指通过物联网技术将家中的各种设备连接到网络，可以实现家电控制、照明控制、防盗报警、环境监测；智慧交通是指将物联网技术有效运用于交通管理的智能化交通运输服务系统，通过对车辆、驾驶者、道路三个方面的数据进行处理，提供实时、全面、准确的交通信息，从而高效地利用交通资源。智慧物流以信息技术为支撑，在运输、仓储、包装、装卸搬运、流通加工、配送、信息服务等各个环节实现系统感知、全面分析。\",\"questionId\":438,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":5,\"wordCount\":196},{\"answer\":\"A\",\"optionA\":\"感知层\",\"optionB\":\"网络层\",\"optionC\":\"平台层\",\"optionD\":\"应用层\",\"orderNum\":2,\"params\":{},\"questionContent\":\"智能温度传感器、RFID 读卡器，在物联网四层架构中属于？（  ）\\n\",\"questionId\":440,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"感知层\",\"optionB\":\"网络层\",\"optionC\":\"应用层\",\"optionD\":\"平台层\",\"orderNum\":3,\"params\":{},\"questionContent\":\"负责数据传输与网络互联的 WiFi 路由器、蓝牙模块，归属架构中的（  ）\\n\\n\",\"questionId\":441,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"感知层\",\"optionB\":\"网络层\",\"optionC\":\"平台层\",\"optionD\":\"应用层\",\"orderNum\":4,\"params\":{},\"questionContent\":\"手机端智能家居控制 APP，属于物联网架构的（  ）\",\"questionId\":442,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"A\",\"optionA\":\"交通领域，通过智能交通系统，可以实时收集和分析交通流量，实现信号灯的智能调控。\",\"optionB\":\"文学创作领域，辅助作者进行散文、诗歌的写作。\",\"optionC\":\"手工制作领域，指导人们进行陶艺、编织等手工创作。\",\"optionD\":\"书法绘画领域，帮助人们练习毛笔字和国画。\",\"orderNum\":5,\"params\":{},\"questionContent\":\"假设你参与了一个关于“智慧城市”的项目，你认为物联网技术有可能在以下哪个领域发挥重要作用？\",\"questionId\":449,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"optionA\":\"小明使用手机闹钟每天定时起床，与以往相比生活更加规律。\",\"optionB\":\"小红家中的智能温控系统根据室内外温差自动调节室内温度，使居住环境更加舒适节能。\",\"optionC\":\"李老师在课堂上使用PPT讲解知识，与以往板书教学相比提高了教学效率。\",\"optionD\":\"小刚通过手机APP查看天气预报，提前准备出行衣物。\",\"orderNum\":6,\"params\":{},\"questionContent\":\"以下哪个场景应用了物联网技术？\",\"questionId\":448,\"questionScore\":5,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"optionA\":\"全面感知\",\"optionB\":\"可靠传递\",\"optionC\":\"智能处理\",\"optionD\":\"离线操控\",\"', 0, NULL, '2026-03-17 16:17:25', 27);
INSERT INTO `sys_oper_log` VALUES (1400, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '960250', '大目湾学校(初中部)', '/business/lesson/save-all', '10.52.27.117', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\",\"4班\",\"8班\",\"7班\",\"6班\",\"5班\"],\"grade\":7,\"lessonId\":57,\"lessonNum\":2,\"lessonTitle\":\"走进物联网\",\"params\":{},\"questions\":[{\"answer\":\"\",\"lessonId\":57,\"optionA\":\"\",\"optionB\":\"\",\"optionC\":\"\",\"optionD\":\"\",\"orderNum\":1,\"params\":{},\"questionContent\":\"物联网是互联网充分发展的产物，是物理世界和数字世界之间的桥梁。物联网具有全面感知、可靠传递、智能处理等特征。物联网一般由感知层、网络层、平台层、应用层四层组成。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。感知层是物联网的底层，相当于人的眼、耳等器官，负责物联网的物体识别和信息采集。平台层是在云平台基础上构建的基础计算设施，功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。应用层是物联网和用户的接口。\",\"questionId\":167,\"questionScore\":60,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":6,\"wordCount\":222},{\"answer\":\"D\",\"lessonId\":57,\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":2,\"params\":{},\"questionContent\":\"水分传感器是物联网架构中（     ）的设备？\",\"questionId\":161,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"D\",\"lessonId\":57,\"optionA\":\"全面感知\",\"optionB\":\"可靠传递\",\"optionC\":\"可靠决策\",\"optionD\":\"智能处理\",\"orderNum\":3,\"params\":{},\"questionContent\":\"利用云计算、数据挖掘以及模糊识别等智能技术，对接收到的海量数据与信息进行分析、处理，以进行智能化决策，体现了物联网的（         ）特征。\",\"questionId\":162,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":57,\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":4,\"params\":{},\"questionContent\":\"物联网的（       ）功能相当于人的大脑，运用智能技术对海量数据和信息进行处理。\",\"questionId\":163,\"questionScore\":10,\"questionType\":\"choice\",\"scoringItems\":[]},{\"answer\":\"B\",\"lessonId\":57,\"optionA\":\"应用层\",\"optionB\":\"平台层\",\"optionC\":\"网络层\",\"optionD\":\"感知层\",\"orderNum\":5,\"params\":{},\"questionContent\":\"自动浇灌物联系统原型中，物联数据中台是属于（       ）