INSERT INTO `sys_oper_log` VALUES (1422, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/question', '10.52.27.200', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-03-18 12:14:40\",\"creatorId\":104,\"filePath\":\"/profile/upload/2026/03/18/学习单_20260318121429A346.docx\",\"grade\":6,\"isPublic\":\"Y\",\"lessonNum\":5,\"params\":{},\"previewPath\":\"/profile/upload/2026/03/18/学习单_20260318121429A346.pdf\",\"previewStatus\":\"pending\",\"questionContent\":\"控制系统中的数据\",\"questionId\":450,\"questionType\":\"practical\",\"scoringItems\":[{\"itemId\":80,\"itemName\":\"答案是否合理\",\"itemScore\":100,\"orderNum\":0,\"params\":{},\"questionId\":450}],\"semester\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-18 12:14:40', 18);
INSERT INTO `sys_oper_log` VALUES (1423, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '19157727791', '大目湾学校(小学部)', '/business/question', '10.52.27.200', '内网IP', '{\"createBy\":\"19157727791\",\"createTime\":\"2026-03-18 12:18:33\",\"creatorId\":104,\"grade\":6,\"isPublic\":\"Y\",\"lessonNum\":5,\"params\":{},\"questionContent\":\"控制系统的运行离不开数据，其形态主要分为连续量和开关量。大小随时间连续变化的数据称为连续量，用来控制设备开与关等只有两种状态的数据称为开关量。数据在控制系统中不断转换，它是系统准确运行的关键媒介。数据能够真实反映控制对象的运行状况。\",\"questionId\":451,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":116}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-18 12:18:33', 9);
