INSERT INTO `sys_oper_log` VALUES (1426, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '683927', '大徐小学', '/business/question', '10.52.113.240', '内网IP', '{\"createBy\":\"683927\",\"createTime\":\"2026-03-18 12:33:19\",\"creatorId\":1881,\"grade\":4,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"信息科技的发展为人类创造了一个全新的数字化生活环境。数字化后的数据可以更方便地在数字设备中存储、处理和传输。将复杂多样的信息转化为计算机可以识别并处理的数据，这个过程就是数字化。数字技术的广泛应用极大地改善并丰富了人们解决问题的方法。例如：数字图书馆让人们足不出户就可以获取所需的学习资源；公共场所的数字摄像设备可及时捕捉安保数据，有力地保障社会的安全。随着数字技术在各领域的普及，人们迈入数字化生活时代。如人们可以使用智能手机、平板电脑等数字设备，拍照、录音和观看视频，便捷地参与在线学习、在线协作、在线零售、在线政务等活动。\",\"questionId\":452,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":14,\"wordCount\":264}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-18 12:33:20', 9);
