INSERT INTO `sys_oper_log` VALUES (1437, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '683927', '大徐小学', '/business/question', '10.52.113.240', '内网IP', '{\"createBy\":\"683927\",\"createTime\":\"2026-03-18 13:17:47\",\"creatorId\":1881,\"grade\":5,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"系统是由多个要素以一定结构联结而成且具有特定功能的有机整体。系统虽然各不相同，但它们都具有整体性和目的性。在现实世界中，系统具有普遍性和多样性。形形色色的系统互相交织，集合在一起，构成了丰富多彩的世界。 \",\"questionId\":453,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":6,\"wordCount\":101}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-18 13:17:47', 10);
