INSERT INTO `sys_oper_log` VALUES (1440, '题库管理', 1, 'com.ruoyi.business.controller.BizQuestionController.add()', 'POST', 1, '683927', '大徐小学', '/business/question', '10.52.113.240', '内网IP', '{\"createBy\":\"683927\",\"createTime\":\"2026-03-18 13:32:32\",\"creatorId\":1881,\"grade\":6,\"isPublic\":\"Y\",\"lessonNum\":1,\"params\":{},\"questionContent\":\"生活中，我们身边藏着许多神奇的自动控制系统。例如，智能家居中的自动感应灯，当天黑有人经过时，它能自动亮起；当人离开后，它又会自动熄灭，非常节能。在农业领域，智慧农场利用计算机技术，通过土壤湿度传感器采集数据。当土壤干燥时，计算机会指令灌溉系统自动喷水；湿度达标后则自动停止。\",\"questionId\":454,\"questionType\":\"typing\",\"scoringItems\":[],\"semester\":\"1\",\"typingDuration\":7,\"wordCount\":137}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-03-18 13:32:32', 8);
INSERT INTO `sys_oper_log` VALUES (1441, '课程设计与指派', 1, 'com.ruoyi.business.controller.BizLessonController.saveAll()', 'POST', 1, '683927', '大徐小学', '/business/lesson/save-all', '10.52.113.240', '内网IP', '{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\"],\"grade\":6,\"lessonId\":78,\"lessonNum\":1,\"lessonTitle\":\"自动控制系统\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"生活中，我们身边藏着许多神奇的自动控制系统。例如，智能家居中的自动感应灯，当天黑有人经过时，它能自动亮起；当人离开后，它又会自动熄灭，非常节能。在农业领域，智慧农场利用计算机技术，通过土壤湿度传感器采集数据。当土壤干燥时，计算机会指令灌溉系统自动喷水；湿度达标后则自动停止。\",\"questionId\":454,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":7,\"wordCount\":137}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}', '{\"msg\":\"操作成功\",\"code\":200,\"data\":{\"assignedClassCodes\":[\"1班\",\"2班\",\"3班\"],\"grade\":6,\"lessonId\":78,\"lessonNum\":1,\"lessonTitle\":\"自动控制系统\",\"params\":{},\"questions\":[{\"orderNum\":1,\"params\":{},\"questionContent\":\"生活中，我们身边藏着许多神奇的自动控制系统。例如，智能家居中的自动感应灯，当天黑有人经过时，它能自动亮起；当人离开后，它又会自动熄灭，非常节能。在农业领域，智慧农场利用计算机技术，通过土壤湿度传感器采集数据。当土壤干燥时，计算机会指令灌溉系统自动喷水；湿度达标后则自动停止。\",\"questionId\":454,\"questionScore\":100,\"questionType\":\"typing\",\"scoringItems\":[],\"typingDuration\":7,\"wordCount\":137}],\"randomChoiceCount\":0,\"randomJudgmentCount\":0,\"semester\":\"1\",\"shuffleMode\":0}}', 0, NULL, '2026-03-18 13:33:49', 19);
